export interface MatchData {
  id: number; // Internal ID for keys
  MacSaati: string;
  Lig: string;
  EvSahibi: string;
  KonukEkip: string;
  IlkYariSonucu: string;
  MacSonucu: string;
  Ms1: string | number;
  Ms0: string | number;
  Ms2: string | number;
  Alt25: string | number;
  Ust25: string | number;
  Iy1: string | number;
  Iy0: string | number;
  Iy2: string | number;
  KgVar: string | number;
  KgYok: string | number;
  SkorDiger: string;
  AIlkYariMacSonucu: string;
  [key: string]: string | number; // Index signature for dynamic access
}

export type FilterState = {
  [key in keyof MatchData]?: string;
};

export const COLUMNS: (keyof MatchData)[] = [
  "MacSaati",
  "Lig",
  "EvSahibi",
  "KonukEkip",
  "IlkYariSonucu",
  "MacSonucu",
  "Ms1",
  "Ms0",
  "Ms2",
  "Alt25",
  "Ust25",
  "Iy1",
  "Iy0",
  "Iy2",
  "KgVar",
  "KgYok",
  "SkorDiger",
  "AIlkYariMacSonucu"
];

import * as XLSX from 'xlsx';
import { MatchData, COLUMNS } from '../types';

export const parseExcelFile = async (file: File): Promise<MatchData[]> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];

        // Convert to JSON
        const rawData = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

        // Assume first row is header
        const headers = rawData[0] as string[];
        const rows = rawData.slice(1) as any[][];

        const mappedData: MatchData[] = rows.map((row, index) => {
          const item: any = { id: index };
          // Map based on known columns to ensure structure, or fallback to index
          COLUMNS.forEach((col, colIndex) => {
            // Find the index in the file's header that matches our column name
            // Or just map sequentially if headers aren't perfect
            const fileHeaderIndex = headers.indexOf(col);
            if (fileHeaderIndex > -1) {
               item[col] = row[fileHeaderIndex] || "-";
            } else {
               // Fallback: assume the order in file matches our COLUMNS list
               item[col] = row[colIndex] || "-";
            }
          });
          return item as MatchData;
        });

        resolve(mappedData);
      } catch (error) {
        reject(error);
      }
    };

    reader.onerror = (error) => reject(error);
    reader.readAsBinaryString(file);
  });
};

import React, { useRef, useState } from 'react';
import { Upload, FileSpreadsheet, Loader2 } from 'lucide-react';

interface FileUploadProps {
  onFileUpload: (file: File) => void;
  isLoading: boolean;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onFileUpload, isLoading }) => {
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      onFileUpload(e.dataTransfer.files[0]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      onFileUpload(e.target.files[0]);
    }
  };

  return (
    <div
      className={`relative w-full h-64 border-2 border-dashed rounded-xl flex flex-col items-center justify-center transition-all duration-300 ${
        isDragging
          ? 'border-blue-500 bg-blue-50'
          : 'border-gray-300 bg-white hover:border-gray-400'
      }`}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      <input
        type="file"
        accept=".xlsx, .xls, .csv"
        className="hidden"
        ref={fileInputRef}
        onChange={handleFileChange}
      />

      {isLoading ? (
        <div className="flex flex-col items-center text-blue-600">
          <Loader2 className="w-12 h-12 animate-spin mb-4" />
          <p className="font-semibold text-lg">Veriler işleniyor...</p>
          <p className="text-sm text-gray-500 mt-2">Büyük dosyalar için bu işlem biraz sürebilir.</p>
        </div>
      ) : (
        <div className="flex flex-col items-center text-gray-500 text-center p-4">
          <div className="bg-green-100 p-4 rounded-full mb-4">
            <FileSpreadsheet className="w-10 h-10 text-green-600" />
          </div>
          <p className="text-xl font-semibold text-gray-700 mb-2">
            Excel Dosyasını Buraya Sürükleyin
          </p>
          <p className="text-sm mb-6 max-w-sm">
            veya dosya seçmek için tıklayın. .xlsx ve .csv formatları desteklenir.
          </p>
          <button
            onClick={() => fileInputRef.current?.click()}
            className="px-6 py-2.5 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded-lg transition-colors flex items-center shadow-lg shadow-blue-600/20"
          >
            <Upload className="w-4 h-4 mr-2" />
            Dosya Seç
          </button>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { MatchData, COLUMNS, FilterState } from '../types';
import { Filter, ArrowUp, ArrowDown } from 'lucide-react';

interface VirtualTableProps {
  data: MatchData[];
}

// Height of a single row in pixels
const ROW_HEIGHT = 35;
// Height of the header in pixels
const HEADER_HEIGHT = 80;

export const VirtualTable: React.FC<VirtualTableProps> = ({ data }) => {
  const [filters, setFilters] = useState<FilterState>({});
  const [sortConfig, setSortConfig] = useState<{ key: keyof MatchData; direction: 'asc' | 'desc' } | null>(null);
  const [scrollTop, setScrollTop] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);

  // 1. Filtering Logic (Memoized)
  const filteredData = useMemo(() => {
    if (Object.keys(filters).length === 0) return data;

    return data.filter((item) => {
      return Object.entries(filters).every(([key, value]) => {
        if (!value) return true;
        const itemValue = String(item[key as keyof MatchData]).toLowerCase();
        return itemValue.includes(value.toLowerCase());
      });
    });
  }, [data, filters]);

  // 2. Sorting Logic (Memoized)
  const sortedData = useMemo(() => {
    if (!sortConfig) return filteredData;

    return [...filteredData].sort((a, b) => {
      const aValue = a[sortConfig.key];
      const bValue = b[sortConfig.key];

      if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
      if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
  }, [filteredData, sortConfig]);

  // 3. Virtualization Logic
  const totalHeight = sortedData.length * ROW_HEIGHT;
  const viewportHeight = 600; // Fixed height for the table container
  const startIndex = Math.floor(scrollTop / ROW_HEIGHT);
  // Render a buffer of 10 items outside viewport for smooth scrolling
  const buffer = 10;
  const visibleStartIndex = Math.max(0, startIndex - buffer);
  const visibleEndIndex = Math.min(
    sortedData.length,
    Math.ceil((scrollTop + viewportHeight) / ROW_HEIGHT) + buffer
  );

  const visibleData = sortedData.slice(visibleStartIndex, visibleEndIndex);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  };

  const handleFilterChange = (column: keyof MatchData, value: string) => {
    setFilters((prev) => ({
      ...prev,
      [column]: value,
    }));
  };

  const handleSort = (column: keyof MatchData) => {
    setSortConfig((current) => {
      if (current?.key === column && current.direction === 'asc') {
        return { key: column, direction: 'desc' };
      }
      return { key: column, direction: 'asc' };
    });
  };

  return (
    <div className="border rounded-lg shadow-xl bg-white overflow-hidden flex flex-col h-[700px]">
      <div className="bg-gray-100 p-2 border-b flex justify-between items-center text-xs text-gray-500">
        <span>Toplam Kayıt: {data.length.toLocaleString()}</span>
        <span>Gösterilen: {filteredData.length.toLocaleString()}</span>
      </div>

      {/* Scrollable Container */}
      <div 
        ref={containerRef}
        className="overflow-auto relative flex-1"
        onScroll={handleScroll}
        style={{ height: viewportHeight }}
      >
        {/* Header - Sticky */}
        <div className="sticky top-0 z-10 grid min-w-max" style={{ gridTemplateColumns: `repeat(${COLUMNS.length}, minmax(100px, 1fr))` }}>
           {COLUMNS.map((col) => (
             <div key={col} className="bg-red-600 text-white border-r border-red-700 p-1 flex flex-col gap-1 h-[80px] shadow-sm">
                <div 
                  className="flex items-center justify-between font-bold text-xs cursor-pointer hover:bg-red-700 p-1 rounded transition-colors select-none"
                  onClick={() => handleSort(col)}
                >
                  <span className="truncate" title={col}>{col}</span>
                  {sortConfig?.key === col && (
                    sortConfig.direction === 'asc' ? <ArrowUp size={12} /> : <ArrowDown size={12} />
                  )}
                </div>
                <div className="relative">
                  <input
                    type="text"
                    placeholder="Ara..."
                    className="w-full text-xs text-gray-800 px-1 py-1 rounded border border-red-800 focus:outline-none focus:ring-1 focus:ring-yellow-300"
                    onChange={(e) => handleFilterChange(col, e.target.value)}
                    value={filters[col] || ''}
                  />
                  <Filter size={10} className="absolute right-1 top-1.5 text-gray-400 pointer-events-none" />
                </div>
             </div>
           ))}
        </div>

        {/* Data Container with Calculated Height */}
        <div style={{ height: totalHeight, position: 'relative', minWidth: 'max-content' }}>
          {/* Rendered Items Positioned Absolute */}
          {visibleData.map((row, index) => {
             // Calculate actual top position based on original index in sorted list
             const actualIndex = visibleStartIndex + index;
             const top = actualIndex * ROW_HEIGHT;

             return (
              <div
                key={row.id}
                className="absolute w-full grid hover:bg-blue-50 transition-colors border-b border-gray-100"
                style={{ 
                  top, 
                  height: ROW_HEIGHT,
                  gridTemplateColumns: `repeat(${COLUMNS.length}, minmax(100px, 1fr))` 
                }}
              >
                {COLUMNS.map((col) => (
                  <div key={`${row.id}-${col}`} className="px-2 flex items-center text-xs text-gray-700 border-r border-gray-100 truncate">
                    <span title={String(row[col])}>{row[col]}</span>
                  </div>
                ))}
              </div>
             );
          })}
        </div>

        {sortedData.length === 0 && (
          <div className="absolute inset-0 flex items-center justify-center text-gray-500">
            Kayıt bulunamadı.
          </div>
        )}
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { MatchData } from "../types";

export const analyzeData = async (dataSample: MatchData[], query: string): Promise<string> => {
  if (!process.env.API_KEY) {
    return "API Key tanımlanmamış.";
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // We can't send 300k rows. We send a statistical sample or the top rows.
  // For this demo, let's take the first 50 rows as context to understand the structure
  // or assume the user has filtered down to a manageable size.
  const dataContext = JSON.stringify(dataSample.slice(0, 50));

  const prompt = `
    Aşağıda bir spor bahis veri setinden örnek veriler bulunmaktadır (JSON formatında).

    Veri Örneği:
    ${dataContext}

    Kullanıcı Sorusu: "${query}"

    Bu verilere dayanarak, veri setinin yapısını ve içeriğini göz önünde bulundurarak bir cevap veya analiz üret. 
    Eğer kesin istatistik veremiyorsan, genel eğilimlerden bahset veya verinin nasıl yorumlanması gerektiğini açıkla.
    Cevabı Türkçe ver. Kısa ve öz ol.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "Analiz yapılamadı.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Yapay zeka servisine bağlanırken bir hata oluştu.";
  }
};

import React, { useState } from 'react';
import { Sparkles, Send, Bot } from 'lucide-react';
import { MatchData } from '../types';
import { analyzeData } from '../services/geminiService';

interface SmartAssistantProps {
  data: MatchData[];
}

export const SmartAssistant: React.FC<SmartAssistantProps> = ({ data }) => {
  const [query, setQuery] = useState('');
  const [response, setResponse] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [isOpen, setIsOpen] = useState(false);

  const handleAsk = async () => {
    if (!query.trim()) return;
    setLoading(true);
    setResponse(null);

    const result = await analyzeData(data, query);
    setResponse(result);
    setLoading(false);
  };

  return (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col items-end">
      {isOpen && (
        <div className="mb-4 w-80 md:w-96 bg-white rounded-2xl shadow-2xl border border-gray-200 overflow-hidden animate-in slide-in-from-bottom-5 fade-in duration-300">
          <div className="bg-gradient-to-r from-indigo-600 to-purple-600 p-4 flex justify-between items-center">
            <div className="flex items-center text-white">
              <Sparkles className="w-5 h-5 mr-2" />
              <h3 className="font-bold">Veri Asistanı</h3>
            </div>
            <span className="text-xs text-indigo-200 bg-indigo-800 px-2 py-1 rounded">Gemini Powered</span>
          </div>

          <div className="p-4 bg-gray-50 h-64 overflow-y-auto">
            {response ? (
              <div className="flex gap-3">
                <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center flex-shrink-0">
                  <Bot className="w-5 h-5 text-indigo-600" />
                </div>
                <div className="bg-white p-3 rounded-lg shadow-sm text-sm text-gray-700 border border-gray-100">
                  {response}
                </div>
              </div>
            ) : (
              <div className="text-center text-gray-400 mt-10 text-sm px-4">
                <p>Şu anki tablo görünümü hakkında soru sorabilirsiniz.</p>
                <p className="mt-2 text-xs">Örnek: "Bu verilerdeki en yüksek oran hangisi?"</p>
              </div>
            )}
          </div>

          <div className="p-3 bg-white border-t border-gray-100">
            <div className="relative">
              <input
                type="text"
                className="w-full pl-4 pr-10 py-2 rounded-full bg-gray-100 border-none focus:ring-2 focus:ring-indigo-500 text-sm"
                placeholder="Bir soru sor..."
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleAsk()}
              />
              <button 
                onClick={handleAsk}
                disabled={loading}
                className="absolute right-1 top-1 p-1.5 bg-indigo-600 text-white rounded-full hover:bg-indigo-700 transition-colors disabled:opacity-50"
              >
                {loading ? <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" /> : <Send className="w-3.5 h-3.5" />}
              </button>
            </div>
          </div>
        </div>
      )}

      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`p-4 rounded-full shadow-lg transition-all duration-300 ${isOpen ? 'bg-red-500 rotate-45' : 'bg-indigo-600 hover:bg-indigo-700'}`}
      >
        {isOpen ? <span className="text-white font-bold text-xl">+</span> : <Sparkles className="text-white w-6 h-6" />}
      </button>
    </div>
  );
};

import React, { useState } from 'react';
