                <br/>
                <span className="text-sm opacity-75">(İstemci tabanlı çalıştığı için verileriniz sunucuya gönderilmez.)</span>
              </p>
            </div>
            <FileUpload onFileUpload={handleFileUpload} isLoading={isLoading} />

            <div className="mt-12 grid grid-cols-1 md:grid-cols-3 gap-6 text-center">
              <div className="p-4 bg-white rounded-lg shadow-sm border border-gray-100">
                <h3 className="font-bold text-gray-900 mb-2">Yüksek Performans</h3>
                <p className="text-sm text-gray-500">300.000+ satırlık verilerde bile takılmadan gezinme.</p>
              </div>
              <div className="p-4 bg-white rounded-lg shadow-sm border border-gray-100">
                <h3 className="font-bold text-gray-900 mb-2">Akıllı Filtreleme</h3>
                <p className="text-sm text-gray-500">Sütun bazlı çoklu filtreleme ile aradığınızı anında bulun.</p>
              </div>
              <div className="p-4 bg-white rounded-lg shadow-sm border border-gray-100">
                <h3 className="font-bold text-gray-900 mb-2">Güvenli</h3>
                <p className="text-sm text-gray-500">Veriler tarayıcınızdan çıkmaz, %100 gizlilik sağlar.</p>
              </div>
            </div>
          </div>
        ) : (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <VirtualTable data={data} />
            <div className="mt-4 text-center text-xs text-gray-400">
               Tablo sanallaştırma teknolojisi ile {data.length.toLocaleString()} satır optimize edilmiştir.
            </div>
