      </div>

      {/* Scrollable Container */}
      <div 
        ref={containerRef}
        className="overflow-auto relative flex-1 w-full bg-gray-50"
        onScroll={handleScroll}
      >
        {/* Content Wrapper with exact width to enforce alignment */}
        <div style={{ width: totalTableWidth, minWidth: '100%' }}>

