  const loadUsers = () => {
    setUsers(authService.getUsers().filter(u => u.username !== 'admin')); // Don't show self
  };

  useEffect(() => {
    loadUsers();
  }, []);

  const handleDelete = (username: string) => {
    if (window.confirm(`${username} kullanıcısını silmek istediğinize emin misiniz? Bu işlem geri alınamaz.`)) {
      authService.deleteUser(username);
      loadUsers();
    }
  };

  const handleBanToggle = (user: User) => {
    const newRole = user.role === 'banned' ? 'free' : 'banned';
    const action = newRole === 'banned' ? 'yasaklamak' : 'yasağını kaldırmak';

    if (window.confirm(`${user.username} kullanıcısını ${action} istediğinize emin misiniz?`)) {
      authService.updateUser({ ...user, role: newRole });
      loadUsers();
    }
  };

  const handleGrantPremium = (username: string) => {
    authService.addPremiumTime(username, selectedDuration);
    loadUsers();
    alert(`${username} kullanıcısına süre eklendi.`);
  };

  const formatTime = (timestamp?: number) => {
    if (!timestamp) return '-';
    if (timestamp < Date.now()) return <span className="text-red-500">Süresi Doldu</span>;

    const date = new Date(timestamp);
    return date.toLocaleString('tr-TR');
  };

  const calculateRemaining = (timestamp?: number) => {
    if (!timestamp || timestamp < Date.now()) return '';
    const diff = timestamp - Date.now();
    const minutes = Math.floor(diff / 60000);
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);

    if (days > 0) return `${days} gün kaldı`;
    if (hours > 0) return `${hours} saat kaldı`;
    return `${minutes} dk kaldı`;
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden mb-8 animate-in fade-in slide-in-from-top-4">
      <div className="bg-slate-800 text-white p-4 flex justify-between items-center">
        <h2 className="font-bold flex items-center gap-2">
           <Crown className="text-amber-400" size={20} />
           Kullanıcı Yönetim Paneli
        </h2>
        <button onClick={loadUsers} className="p-2 hover:bg-slate-700 rounded-full transition-colors">
            <RefreshCcw size={16} />
        </button>
      </div>

      <div className="p-4 overflow-x-auto">
        <table className="w-full text-sm text-left">
            <thead className="bg-gray-50 text-gray-500 uppercase font-bold text-xs">
                <tr>
                    <th className="px-4 py-3">Kullanıcı Adı</th>
                    <th className="px-4 py-3">Durum</th>
                    <th className="px-4 py-3">Premium Bitiş</th>
                    <th className="px-4 py-3">Süre Ekle</th>
                    <th className="px-4 py-3 text-right">İşlemler</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
                {users.length === 0 ? (
                    <tr>
                        <td colSpan={5} className="text-center py-8 text-gray-400">Henüz kayıtlı üye yok.</td>
                    </tr>
                ) : users.map(user => (
                    <tr key={user.username} className="hover:bg-gray-50">
                        <td className="px-4 py-3 font-medium text-gray-900">{user.username}</td>
                        <td className="px-4 py-3">
                            <span className={`px-2 py-1 rounded text-xs font-semibold ${
                                user.role === 'premium' ? 'bg-amber-100 text-amber-700' :
                                user.role === 'banned' ? 'bg-red-100 text-red-700' :
                                'bg-blue-100 text-blue-700'
                            }`}>
                                {user.role === 'premium' ? 'Premium' : user.role === 'banned' ? 'Yasaklı' : 'Ücretsiz'}
                            </span>
                        </td>
                        <td className="px-4 py-3 text-gray-600">
                           <div className="flex flex-col">
                               <span>{formatTime(user.premiumExpiresAt)}</span>
                               <span className="text-[10px] text-blue-500 font-medium">{calculateRemaining(user.premiumExpiresAt)}</span>
                           </div>
                        </td>
                        <td className="px-4 py-3">
                            <div className="flex items-center gap-2">
                                <select 
                                    className="border border-gray-300 rounded px-2 py-1 text-xs"
                                    onChange={(e) => setSelectedDuration(Number(e.target.value))}
                                >
                                    <option value={1}>1 Dakika (Test)</option>
                                    <option value={1440}>1 Gün</option>
                                    <option value={10080}>1 Hafta</option>
                                    <option value={43200}>1 Ay</option>
                                    <option value={129600}>3 Ay (90 Gün)</option>
                                </select>
                                <button 
                                    onClick={() => handleGrantPremium(user.username)}
                                    className="p-1.5 bg-green-500 text-white rounded hover:bg-green-600 transition-colors"
                                    title="Süre Ekle"
                                >
                                    <CheckCircle2 size={16} />
                                </button>
                            </div>
                        </td>
                        <td className="px-4 py-3 text-right">
                            <div className="flex items-center justify-end gap-2">
                                <button 
                                    onClick={() => handleBanToggle(user)}
                                    className={`p-1.5 rounded transition-colors ${user.role === 'banned' ? 'bg-gray-500 text-white hover:bg-gray-600' : 'bg-red-100 text-red-600 hover:bg-red-200'}`}
                                    title={user.role === 'banned' ? "Yasağı Kaldır" : "Yasakla"}
                                >
                                    <Ban size={16} />
                                </button>
                                <button 
                                    onClick={() => handleDelete(user.username)}
                                    className="p-1.5 bg-slate-100 text-slate-600 rounded hover:bg-slate-200 transition-colors"
                                    title="Kullanıcıyı Sil"
                                >
                                    <Trash2 size={16} />
                                </button>
                            </div>
                        </td>
                    </tr>
                ))}
            </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { FileUpload } from './components/FileUpload';
import { VirtualTable } from './components/VirtualTable';
import { SmartAssistant } from './components/SmartAssistant';
import { Auth } from './components/Auth';
import { UpgradeAlert } from './components/UpgradeAlert';
import { AdminPanel } from './components/AdminPanel';
import { parseExcelFile } from './utils/excelParser';
import { MatchData, User } from './types';
import { authService } from './services/authService';
import { Database, AlertCircle, LogOut, Crown, Shield, Clock } from 'lucide-react';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [masterData, setMasterData] = useState<MatchData[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // State to force re-render for timer
  const [now, setNow] = useState(Date.now());

  // Check login status on mount
  useEffect(() => {
     // Optional: If we wanted auto-login, we could implement token check here.
     // For this demo, we rely on Auth component's flow, but we start the timer.
     const interval = setInterval(() => {
         setNow(Date.now());
         checkPremiumStatus();
     }, 1000);

     return () => clearInterval(interval);
  }, [user]);

  const checkPremiumStatus = () => {
      if (user && user.role === 'premium' && user.premiumExpiresAt) {
          if (Date.now() > user.premiumExpiresAt) {
              const updatedUser: User = { ...user, role: 'free', premiumExpiresAt: undefined };
              authService.updateUser(updatedUser);
              setUser(updatedUser);
              alert("Premium süreniz doldu. Demo versiyona geçiş yapıldı.");
          }
      }
  };

  const handleLogin = (userData: User) => {
    setUser(userData);
  };

  const handleLogout = () => {
    setUser(null);
    setMasterData([]);
  };

  const handleFileUpload = async (file: File) => {
    setIsLoading(true);
    setError(null);
    try {
      setTimeout(async () => {
        try {
            const parsedData = await parseExcelFile(file);
            setMasterData(parsedData);
            setIsLoading(false);
        } catch (err) {
            console.error(err);
            setError("Dosya işlenirken bir hata oluştu. Lütfen formatı kontrol edin.");
            setIsLoading(false);
        }
      }, 100);
    } catch (err) {
      setError("Beklenmedik bir hata oluştu.");
      setIsLoading(false);
    }
  };

  const handleReset = () => {
    setMasterData([]);
    setError(null);
  };

  // Logic to determine what data the user sees
  const displayedData = useMemo(() => {
    if (!user) return [];
    if (user.role === 'admin' || user.role === 'premium') {
        return masterData;
    }
    // Free user gets limited data
    return masterData.slice(0, 50);
  }, [user, masterData]);

  if (!user) {
    return <Auth onLogin={handleLogin} />;
  }

  // Calculate time remaining string
  const timeRemaining = useMemo(() => {
      if(user.role === 'premium' && user.premiumExpiresAt) {
          const diff = Math.max(0, user.premiumExpiresAt - now);
          const minutes = Math.floor(diff / 60000);
          const seconds = Math.floor((diff % 60000) / 1000);

          if(minutes > 60) {
              const hours = Math.floor(minutes / 60);
              return `${hours} Saat Kaldı`;
          }
          return `${minutes}:${seconds < 10 ? '0' : ''}${seconds}`;
      }
      return null;
  }, [user, now]);

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col font-sans text-gray-800">
      {/* Header */}
      <header className="bg-slate-900 text-white border-b border-slate-800 sticky top-0 z-50 shadow-md">
        <div className="max-w-[98%] mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-gradient-to-br from-blue-600 to-purple-600 p-2 rounded-lg shadow-lg shadow-purple-900/20">
              <Database className="w-5 h-5 text-white" />
            </div>
            <div>
                <h1 className="text-lg font-bold tracking-tight text-white leading-tight">
                BetData <span className="text-blue-400">Analyze</span>
                </h1>
                <p className="text-[10px] text-slate-400 uppercase tracking-widest">Profesyonel Panel</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
             {/* Timer Badge for Premium */}
             {user.role === 'premium' && timeRemaining && (
                 <div className="hidden md:flex items-center gap-1 px-3 py-1 bg-gradient-to-r from-amber-500 to-orange-500 rounded-full text-xs font-bold shadow-lg shadow-amber-500/20 animate-pulse">
                     <Clock size={12} />
                     <span>{timeRemaining}</span>
                 </div>
             )}

             {/* Role Badge */}
             <div className={`px-3 py-1 rounded-full text-xs font-bold flex items-center gap-1 border ${
                 user.role === 'admin' ? 'bg-red-500/10 border-red-500/50 text-red-400' : 
                 user.role === 'premium' ? 'bg-amber-500/10 border-amber-500/50 text-amber-400' : 
                 'bg-slate-700 border-slate-600 text-slate-300'
             }`}>
                {user.role === 'admin' && <Shield size={12} />}
                {user.role === 'premium' && <Crown size={12} />}
                {user.role === 'admin' ? 'YÖNETİCİ' : user.role === 'premium' ? 'PREMIUM ÜYE' : 'DEMO HESAP'}
             </div>

             <div className="h-6 w-px bg-slate-700 mx-1"></div>

             <div className="text-right hidden md:block">
                 <div className="text-sm font-medium text-white">{user.username}</div>
             </div>

             <button 
                onClick={handleLogout}
                className="p-2 text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg transition-colors"
                title="Çıkış Yap"
             >
                <LogOut size={18} />
             </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-[98%] w-full mx-auto py-6 px-4 pb-32">
        {error && (
          <div className="mb-6 bg-red-50 border border-red-200 rounded-lg p-4 flex items-center text-red-700">
            <AlertCircle className="w-5 h-5 mr-2 flex-shrink-0" />
            {error}
          </div>
        )}

        {/* Admin Dashboard */}
        {user.role === 'admin' && (
            <div className="flex flex-col gap-6">
                <AdminPanel />

                {masterData.length === 0 && (
                    <div className="mb-8 animate-in fade-in slide-in-from-top-4 duration-500">
                        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200 mb-6">
                            <h2 className="text-xl font-bold text-gray-900 mb-2">Veri Seti Yönetimi</h2>
                            <p className="text-gray-500 mb-6 text-sm">Sisteme yeni bir Excel dosyası yükleyin. Bu veri seti tüm kullanıcılar tarafından görüntülenecektir.</p>
                            <FileUpload onFileUpload={handleFileUpload} isLoading={isLoading} />
                        </div>
                    </div>
                )}
            </div>
        )}

        {/* Data Display Logic */}
        {masterData.length === 0 ? (
           user.role === 'admin' ? null : (
            <div className="flex flex-col items-center justify-center h-[50vh] text-center p-8 bg-white rounded-2xl shadow-sm border border-gray-200 mt-8">
                <div className="bg-blue-50 p-6 rounded-full mb-6 animate-pulse">
                    <Database className="w-12 h-12 text-blue-400" />
                </div>
                <h3 className="text-xl font-bold text-gray-900 mb-2">Veri Bekleniyor</h3>
                <p className="text-gray-500 max-w-md">
                    Şu anda sistemde aktif bir veri seti bulunmamaktadır. Yöneticinin veri yüklemesini bekleyin.
                </p>
            </div>
           )
        ) : (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 flex flex-col gap-4">
             {/* Admin Controls for Data */}
             {user.role === 'admin' && (
                 <div className="flex justify-end">
                     <button 
                       onClick={handleReset}
                       className="text-sm bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2 rounded-lg font-medium transition-colors shadow-sm"
                     >
                       Mevcut Veriyi Sil ve Yeni Yükle
                     </button>
                 </div>
             )}

            <VirtualTable data={displayedData} isDemo={user.role === 'free'} />

            <div className="mt-2 text-center text-xs text-gray-400">
               {user.role === 'free' 
                 ? `Demo Modu: ${masterData.length} kayıttan sadece 50 tanesi gösteriliyor.`
                 : `Toplam ${masterData.length.toLocaleString()} kayıt listeleniyor.`
               }
            </div>
          </div>
        )}
      </main>

      {/* Conditionally render Upgrade Alert for free users if data exists */}
      {user.role === 'free' && masterData.length > 0 && <UpgradeAlert />}

      {/* AI Assistant - Available for everyone but context differs based on data visibility */}
      {masterData.length > 0 && <SmartAssistant data={displayedData} />}
    </div>
  );
};

export default App;

