import { put, list } from '@vercel/blob';

export const config = {
  runtime: 'nodejs',
};

const USERS_FILE = 'users.json';

// Helper to get fresh data from Blob
async function getFreshUsers(token: string) {
  try {
    const { blobs } = await list({ token });
    const userBlob = blobs.find((b: any) => b.pathname === USERS_FILE);

    if (userBlob) {
      // CRITICAL: cache: 'no-store' ensures we always fetch the latest version from Blob storage
      // bypassing Vercel's edge cache which causes the "can't login" issue.
      const res = await fetch(userBlob.url, { cache: 'no-store' });
      if (res.ok) {
        return await res.json();
      }
    }
    // Default admin if no file exists
    return [{ username: 'admin', password: 'admin123', role: 'admin' }];
  } catch (e) {
    console.error("Error reading users blob:", e);
    return [{ username: 'admin', password: 'admin123', role: 'admin' }];
  }
}

export default async function handler(request: any, response: any) {
  const token = process.env.BLOB_READ_WRITE_TOKEN;

  if (!token) {
    return response.status(500).json({ error: 'BLOB_READ_WRITE_TOKEN not configured' });
  }

  try {
    // GET: Return users (Always fresh)
    if (request.method === 'GET') {
      const users = await getFreshUsers(token);

      // Set headers to prevent browser/CDN caching of the API response
      response.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
      return response.status(200).json(users);
    }

    // POST: Handle Actions (Register, Update, Delete)
    // Moving logic here prevents "Race Conditions" where users disappear.
    if (request.method === 'POST') {
      const { action, user, username, users: fullList } = request.body;

      // Fetch current state from server (Single Source of Truth)
      let currentUsers = await getFreshUsers(token);
      let updatedUsers = [...currentUsers];
      let success = false;
      let message = "";

      // Legacy support: If full list is sent (mostly for simple migration/init), overwrite carefully
      if (fullList && Array.isArray(fullList)) {
         updatedUsers = fullList;
         success = true;
      } 
      // ACTION: REGISTER / ADD
      else if (action === 'register' || action === 'add') {
         if (updatedUsers.find((u: any) => u.username === user.username)) {
            return response.status(400).json({ success: false, message: 'Kullanıcı adı zaten var.' });
         }
         updatedUsers.push(user);
         success = true;
      }
      // ACTION: UPDATE
      else if (action === 'update') {
         const index = updatedUsers.findIndex((u: any) => u.username === user.username);
         if (index !== -1) {
             updatedUsers[index] = { ...updatedUsers[index], ...user };
             success = true;
         } else {
             return response.status(404).json({ success: false, message: 'Kullanıcı bulunamadı.' });
         }
      }
      // ACTION: DELETE
      else if (action === 'delete') {
         const initialLength = updatedUsers.length;
         updatedUsers = updatedUsers.filter((u: any) => u.username !== username);
         success = updatedUsers.length < initialLength;
      }

      if (success) {
        // Save back to Blob
        const blob = await put(USERS_FILE, JSON.stringify(updatedUsers), { 
            access: 'public',
            addRandomSuffix: false, // Keep the filename constant
            token,
            // Ensure write doesn't cache
            cacheControlMaxAge: 0 
        });

        return response.status(200).json({ success: true, url: blob.url });
      } else {
        return response.status(400).json({ success: false, message: 'İşlem gerçekleştirilemedi.' });
      }
    }

    return response.status(405).json({ error: 'Method not allowed' });

  } catch (error: any) {
    console.error("API Handler Error:", error);
    return response.status(500).json({ error: error.message || 'Unknown error' });
  }
}

import { User } from '../types';

export const authService = {
  // Fetch users from API (Force fresh data)
  getUsers: async (): Promise<User[]> => {
    try {
      // Add timestamp to prevent browser caching
      const res = await fetch(`/api/users?t=${Date.now()}`, {
        headers: { 
            'Cache-Control': 'no-cache',
            'Pragma': 'no-cache'
        }
      });
      if (!res.ok) return [];
      return await res.json();
    } catch (e) {
      console.error("Error fetching users:", e);
      return [];
    }
  },

  register: async (username: string, password: string): Promise<{ success: boolean; message: string; user?: User }> => {
    // We do NOT fetch all users here anymore. We let the server handle the check.
    const newUser: User = {
      username,
      password,
      role: 'free'
    };

    try {
        const res = await fetch('/api/users', {
            method: 'POST',
            body: JSON.stringify({
                action: 'register',
                user: newUser
            }),
            headers: { 'Content-Type': 'application/json' }
        });

        const data = await res.json();

        if (res.ok && data.success) {
            return { success: true, message: 'Kayıt başarılı.', user: newUser };
        } else {
            return { success: false, message: data.message || 'Kayıt başarısız.' };
        }
    } catch (e) {
        return { success: false, message: 'Sunucu hatası.' };
    }
  },

  login: async (username: string, password: string): Promise<{ success: boolean; message: string; user?: User }> => {
    // For login, we still fetch the list to check credentials client-side for simplicity,
    // but relying on getUsers() which now forces a fresh fetch.
    const users = await authService.getUsers();
    const user = users.find(u => u.username === username && u.password === password);

    if (!user) {
      return { success: false, message: 'Kullanıcı adı veya şifre hatalı.' };
    }

    if (user.role === 'banned') {
      return { success: false, message: 'Bu hesap yasaklanmıştır. Yönetici ile iletişime geçin.' };
    }

    // Check expiration logic
    if (user.role === 'premium' && user.premiumExpiresAt && Date.now() > user.premiumExpiresAt) {
        // Update user on server
        const updatedUser = { ...user, role: 'free' as const, premiumExpiresAt: undefined };
        await authService.updateUser(updatedUser);
        return { success: true, message: 'Premium süreniz doldu, ücretsiz plana geçirildiniz.', user: updatedUser };
    }

    return { success: true, message: 'Giriş başarılı.', user };
  },

  updateUser: async (updatedUser: User): Promise<boolean> => {
    try {
      const res = await fetch('/api/users', {
          method: 'POST',
          body: JSON.stringify({
              action: 'update',
              user: updatedUser
          }),
          headers: { 'Content-Type': 'application/json' }
      });
      const data = await res.json();
      return data.success;
    } catch (e) {
        console.error("Update error:", e);
        return false;
    }
  },

  deleteUser: async (username: string): Promise<boolean> => {
    try {
        const res = await fetch('/api/users', {
            method: 'POST',
            body: JSON.stringify({
                action: 'delete',
                username: username
            }),
            headers: { 'Content-Type': 'application/json' }
        });
        const data = await res.json();
        return data.success;
    } catch (e) {
        console.error("Delete error:", e);
        return false;
    }
  },

  addPremiumTime: async (username: string, durationMinutes: number) => {
    // Need to fetch specific user first to calculate time
    const users = await authService.getUsers();
    const user = users.find(u => u.username === username);

    if (user) {
        const now = Date.now();
        const startTime = (user.role === 'premium' && user.premiumExpiresAt && user.premiumExpiresAt > now) 
            ? user.premiumExpiresAt 
            : now;

        user.role = 'premium';
        user.premiumExpiresAt = startTime + (durationMinutes * 60 * 1000);

        await authService.updateUser(user);
    }
  }
};

import { handleUpload } from '@vercel/blob/client';
import { list } from '@vercel/blob';

export const config = {
  runtime: 'nodejs',
};

const DATA_FILE_ZIP = 'main-data.zip';
const VERSION_FILE = 'version.json';

export default async function handler(request: any, response: any) {
  const token = process.env.BLOB_READ_WRITE_TOKEN;

  if (!token) {
    return response.status(500).json({ error: 'BLOB_READ_WRITE_TOKEN not configured' });
  }

  // GET: Fetch Data or Version
  if (request.method === 'GET') {
    try {
        const { type } = request.query; // ?type=version or default (data)
        const { blobs } = await list({ token });

        if (type === 'version') {
            const versionBlob = blobs.find((b: any) => b.pathname === VERSION_FILE);
            if (!versionBlob) return response.status(200).json({ timestamp: 0 }); // No version yet

            // Bypass cache for version check
            const res = await fetch(versionBlob.url, { cache: 'no-store' });
            const data = await res.json();
            return response.status(200).json(data);
        } 
        else {
            // Get the ZIP file URL
            const dataBlob = blobs.find((b: any) => b.pathname === DATA_FILE_ZIP);
            if (!dataBlob) return response.status(404).json({ error: 'Data not found' });

            // Redirect to the blob URL so the client can download the binary directly
            return response.redirect(dataBlob.url);
        }

    } catch (e: any) {
        return response.status(500).json({ error: e.message || 'Unknown error' });
    }
  }

  // POST: Generate a client upload token
  if (request.method === 'POST') {
    const body = request.body;

    try {
      const jsonResponse = await handleUpload({
        body,
        request,
        onBeforeGenerateToken: async (pathname) => {
          // Allow both the zip file and the version file
          if (pathname !== DATA_FILE_ZIP && pathname !== VERSION_FILE) {
            throw new Error('Invalid filename. Only main-data.zip and version.json allowed.');
          }
          return {
            allowedContentTypes: ['application/zip', 'application/json', 'application/x-zip-compressed'],
            tokenPayload: JSON.stringify({
              userId: 'admin',
            }),
          };
        },
        onUploadCompleted: async ({ blob, tokenPayload }) => {
          console.log('Blob upload completed', blob.pathname);
        },
      });

      return response.status(200).json(jsonResponse);
    } catch (error: any) {
      return response.status(400).json({ error: error.message || 'Upload failed' });
    }
  }

  return response.status(405).json({ error: 'Method not allowed' });
}

import { MatchData } from '../types';
import * as XLSX from 'xlsx';
import { upload } from '@vercel/blob/client';
import * as fflate from 'fflate';
import localforage from 'localforage';

const DATA_FILE_ZIP = 'main-data.zip';
const VERSION_FILE = 'version.json';

// Configure LocalForage
localforage.config({
  name: 'BetDataApp',
  storeName: 'matches'
});

export const dataService = {
  // Save Data: Zips the content, uploads it, and updates the version file
  saveData: async (data: MatchData[]): Promise<void> => {
    try {
      console.log("Sıkıştırma işlemi başlıyor...");
      const jsonString = JSON.stringify(data);

      // 1. Compress Data using fflate
      const zipData = await new Promise<Uint8Array>((resolve, reject) => {
        const bytes = fflate.strToU8(jsonString);
        fflate.zip({ 'data.json': bytes }, { level: 6 }, (err, out) => {
            if (err) reject(err);
            else resolve(out);
        });
      });

      const zipFile = new File([zipData], DATA_FILE_ZIP, { type: 'application/zip' });

      console.log(`Veri sıkıştırıldı. Orijinal: ${(jsonString.length / 1024 / 1024).toFixed(2)}MB, Sıkıştırılmış: ${(zipFile.size / 1024 / 1024).toFixed(2)}MB`);

      // 2. Upload Zip
      await upload(DATA_FILE_ZIP, zipFile, {
        access: 'public',
        handleUploadUrl: '/api/data',
      });

      // 3. Upload Version File
      const newVersion = { timestamp: Date.now(), count: data.length };
      const versionFile = new File([JSON.stringify(newVersion)], VERSION_FILE, { type: 'application/json' });

      await upload(VERSION_FILE, versionFile, {
        access: 'public',
        handleUploadUrl: '/api/data',
      });

      // 4. Update local cache immediately
      await localforage.setItem('dataVersion', newVersion.timestamp);
      await localforage.setItem('matchData', data);

      console.log("Veri ve versiyon bilgisi güncellendi.");
      return;
    } catch (error) {
      console.error("Save Error:", error);
      throw new Error("Veri sıkıştırılırken veya yüklenirken hata oluştu.");
    }
  },

  // Append Data: Downloads full data, unzips, appends, zips, uploads
  appendData: async (newData: MatchData[]): Promise<void> => {
    try {
      const currentData = await dataService.getAllData();

      const startId = currentData.length > 0 ? Math.max(...currentData.map(d => d.id)) + 1 : 0;
      const preparedNewData = newData.map((item, index) => ({
          ...item,
          id: startId + index
      }));

      const combinedData = [...currentData, ...preparedNewData];
      await dataService.saveData(combinedData);
    } catch (error) {
       console.error("Append Error:", error);
       throw error;
    }
  },

  // Get All Data: Smart Fetching (Cache -> Version Check -> Download -> Unzip)
  getAllData: async (): Promise<MatchData[]> => {
    try {
      // 1. Get Server Version
      const versionRes = await fetch('/api/data?type=version', { cache: 'no-store' });
      const serverVersionData = await versionRes.json();
      const serverTimestamp = serverVersionData.timestamp || 0;

      // 2. Get Local Version
      const localTimestamp = await localforage.getItem<number>('dataVersion');

      // 3. Compare
      if (localTimestamp && localTimestamp === serverTimestamp) {
          const cachedData = await localforage.getItem<MatchData[]>('matchData');
          if (cachedData) {
              console.log("Veriler yerel önbellekten yüklendi.");
              return cachedData;
          }
      }

      console.log("Yeni veri indiriliyor...");

      // 4. Download Zip (If version mismatch or no cache)
      const response = await fetch('/api/data'); // Returns 307 Redirect to Blob URL
      if (response.status === 404) return [];

      const blob = await response.blob();
      const arrayBuffer = await blob.arrayBuffer();
      const uint8Array = new Uint8Array(arrayBuffer);

      // 5. Unzip
      const jsonString = await new Promise<string>((resolve, reject) => {
          fflate.unzip(uint8Array, (err, unzipped) => {
              if (err) return reject(err);
              const fileContent = unzipped['data.json'];
              if (fileContent) {
                  resolve(fflate.strFromU8(fileContent));
              } else {
                  reject(new Error("Zip içinde data.json bulunamadı"));
              }
          });
      });

      const data = JSON.parse(jsonString);

      // 6. Update Cache
      await localforage.setItem('dataVersion', serverTimestamp);
      await localforage.setItem('matchData', data);

      console.log("Veri indirildi, açıldı ve önbelleklendi.");
      return Array.isArray(data) ? data : [];

    } catch (error) {
      console.error("Fetch/Unzip Error:", error);
      // Fallback: try to return cache even if error occurs
      const cached = await localforage.getItem<MatchData[]>('matchData');
      return cached || [];
    }
  },

  clearData: async (): Promise<void> => {
     await dataService.saveData([]);
  },

  removeDuplicates: async (): Promise<{ removedCount: number }> => {
    const allData = await dataService.getAllData();
    const uniqueMap = new Map<string, MatchData>();
    let originalCount = allData.length;

    allData.forEach(item => {
        const { id, ...rest } = item;
        const signature = JSON.stringify(rest);
        if (!uniqueMap.has(signature)) {
            uniqueMap.set(signature, item);
        }
    });

    const uniqueData = Array.from(uniqueMap.values());
    const removedCount = originalCount - uniqueData.length;

    if (removedCount > 0) {
        const reIndexedData = uniqueData.map((item, index) => ({
            ...item,
            id: index
        }));
        await dataService.saveData(reIndexedData);
    }

    return { removedCount };
  },

  exportToExcel: async (fileName: string = 'BetData_Export.xlsx'): Promise<void> => {
    const data = await dataService.getAllData();
    if (data.length === 0) return;

    const cleanData = data.map(({ id, ...rest }) => rest);
    const worksheet = XLSX.utils.json_to_sheet(cleanData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Maç Verileri");
    XLSX.writeFile(workbook, fileName);
  }
};

import React, { useEffect, useState } from 'react';
import { User } from '../types';
import { authService } from '../services/authService';
import { Trash2, Ban, CheckCircle2, Crown, RefreshCcw, AlertTriangle, X, CalendarClock, Loader2 } from 'lucide-react';

interface ModalConfig {
  isOpen: boolean;
  type: 'delete' | 'ban' | null;
  user: User | null;
}

export const AdminPanel: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  // Use string for datetime-local input value (YYYY-MM-DDThh:mm)
  const [selectedDate, setSelectedDate] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);
  const [processingUser, setProcessingUser] = useState<string | null>(null);

  const [modalConfig, setModalConfig] = useState<ModalConfig>({ 
    isOpen: false, 
    type: null, 
    user: null 
  });

  const loadUsers = async () => {
    setIsLoading(true);
    try {
        const allUsers = await authService.getUsers();
        setUsers(allUsers.filter(u => u.username !== 'admin'));
    } finally {
        setIsLoading(false);
    }
  };

  useEffect(() => {
    loadUsers();

    // Set default date to tomorrow same time
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    tomorrow.setMinutes(tomorrow.getMinutes() - tomorrow.getTimezoneOffset());
    setSelectedDate(tomorrow.toISOString().slice(0, 16));
  }, []);

  const requestDelete = (user: User) => {
    setModalConfig({ isOpen: true, type: 'delete', user });
  };

  const requestBan = (user: User) => {
    setModalConfig({ isOpen: true, type: 'ban', user });
  };

  const closeModal = () => {
    setModalConfig({ isOpen: false, type: null, user: null });
  };

  const handleConfirmAction = async () => {
    if (!modalConfig.user) return;
    setIsLoading(true);

    // Artificial delay to allow blob propagation
    await new Promise(r => setTimeout(r, 1000));

    if (modalConfig.type === 'delete') {
        const success = await authService.deleteUser(modalConfig.user.username);
        if (success) {
            setUsers(prev => prev.filter(u => u.username !== modalConfig.user!.username));
        } else {
            alert("Kullanıcı silinemedi.");
        }
    } else if (modalConfig.type === 'ban') {
        const user = modalConfig.user;
        const newRole = user.role === 'banned' ? 'free' : 'banned';
        const success = await authService.updateUser({ ...user, role: newRole });
        if (success) {
            setUsers(prev => prev.map(u => u.username === user.username ? { ...u, role: newRole } : u));
        } else {
            alert("Kullanıcı durumu güncellenemedi.");
        }
    }
    setIsLoading(false);
    closeModal();
  };

  const handleSetPremium = async (username: string) => {
    if (!selectedDate) {
        alert("Lütfen geçerli bir tarih seçin.");
        return;
    }

    const timestamp = new Date(selectedDate).getTime();
    if (isNaN(timestamp)) {
         alert("Tarih formatı hatalı.");
         return;
    }

    setProcessingUser(username);

    // 1. Calculate duration in minutes relative to NOW (backend expects minutes currently, or we update backend)
    // Actually, authService.addPremiumTime takes minutes. Let's update the User object directly here using updateUser
    // to allow setting a specific timestamp which is safer.

    const user = users.find(u => u.username === username);
    if(user) {
        const updatedUser = { ...user, role: 'premium' as const, premiumExpiresAt: timestamp };

        const success = await authService.updateUser(updatedUser);

        if(success) {
             // Artificial delay for consistency
             await new Promise(r => setTimeout(r, 1500));
             await loadUsers();
        } else {
            alert("İşlem başarısız.");
        }
    }

    setProcessingUser(null);
  };

  const formatTime = (timestamp?: number) => {
    if (!timestamp) return '-';
    if (timestamp < Date.now()) return <span className="text-red-500 font-bold">Süresi Doldu</span>;

    const date = new Date(timestamp);
    return date.toLocaleString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit'});
  };

  const calculateRemaining = (timestamp?: number) => {
    if (!timestamp || timestamp < Date.now()) return '';
    const diff = timestamp - Date.now();
    const minutes = Math.floor(diff / 60000);
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);

    if (days > 0) return `${days} gün kaldı`;
    if (hours > 0) return `${hours} saat kaldı`;
    return `${minutes} dk kaldı`;
  };

  return (
    <>
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden mb-8 animate-in fade-in slide-in-from-top-4 relative z-0">
      <div className="bg-slate-800 text-white p-4 flex justify-between items-center">
        <h2 className="font-bold flex items-center gap-2">
           <Crown className="text-amber-400" size={20} />
           Kullanıcı Yönetim Paneli
        </h2>
        <div className="flex gap-4 items-center">
            {/* Global Date Picker for Quick Actions */}
            <div className="flex items-center gap-2 bg-slate-700 px-3 py-1 rounded-lg">
                <CalendarClock size={14} className="text-slate-300" />
                <span className="text-xs text-slate-300 mr-1">Bitiş Tarihi:</span>
                <input 
                    type="datetime-local"
                    className="bg-transparent text-white text-xs outline-none cursor-pointer"
                    value={selectedDate}
                    onChange={(e) => setSelectedDate(e.target.value)}
                />
            </div>

            <button 
                type="button"
                onClick={loadUsers} 
                disabled={isLoading}
                className={`p-2 hover:bg-slate-700 rounded-full transition-colors ${isLoading ? 'animate-spin' : ''}`}
                title="Listeyi Yenile"
            >
                <RefreshCcw size={16} />
            </button>
        </div>
      </div>

      <div className="p-4 overflow-x-auto">
        <table className="w-full text-sm text-left">
            <thead className="bg-gray-50 text-gray-500 uppercase font-bold text-xs">
                <tr>
                    <th className="px-4 py-3">Kullanıcı Adı</th>
                    <th className="px-4 py-3">Durum</th>
                    <th className="px-4 py-3">Premium Bitiş</th>
                    <th className="px-4 py-3 text-right">Premium Onayı</th>
                    <th className="px-4 py-3 text-right">İşlemler</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
                {users.length === 0 ? (
                    <tr>
                        <td colSpan={5} className="text-center py-8 text-gray-400">
                            {isLoading ? 'Yükleniyor...' : 'Henüz kayıtlı üye yok.'}
                        </td>
                    </tr>
                ) : users.map(user => (
                    <tr key={user.username} className="hover:bg-gray-50">
                        <td className="px-4 py-3 font-medium text-gray-900">{user.username}</td>
                        <td className="px-4 py-3">
                            <span className={`px-2 py-1 rounded text-xs font-semibold ${
                                user.role === 'premium' ? 'bg-amber-100 text-amber-700' :
                                user.role === 'banned' ? 'bg-red-100 text-red-700' :
                                'bg-blue-100 text-blue-700'
                            }`}>
                                {user.role === 'premium' ? 'Premium' : user.role === 'banned' ? 'Yasaklı' : 'Ücretsiz'}
                            </span>
                        </td>
                        <td className="px-4 py-3 text-gray-600">
                           <div className="flex flex-col">
                               <span>{formatTime(user.premiumExpiresAt)}</span>
                               <span className="text-[10px] text-blue-500 font-medium">{calculateRemaining(user.premiumExpiresAt)}</span>
                           </div>
                        </td>
                        <td className="px-4 py-3 text-right">
                           <button 
                                type="button"
