import React, { useState } from 'react';
import { User } from '../types';
import { LogIn, UserPlus, ShieldCheck, Database, AlertCircle, Loader2 } from 'lucide-react';
import { authService } from '../services/authService';

interface AuthProps {
  onLogin: (user: User) => void;
}

export const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isPreparing, setIsPreparing] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccessMsg('');
    setIsLoading(true);

    try {
        if (isLogin) {
            // Login Logic
            const result = await authService.login(username, password);
            if (result.success && result.user) {
                onLogin(result.user);
            } else {
                setError(result.message);
            }
        } else {
            // Register Logic
            if (password.length < 3) {
                setError('Şifre en az 3 karakter olmalıdır.');
                setIsLoading(false);
                return;
            }

            const result = await authService.register(username, password);
            if (result.success) {
                // Show preparing state to user while we wait a bit
                setIsPreparing(true);
                setSuccessMsg('Kayıt başarılı! Hesap hazırlanıyor, lütfen bekleyin...');

                // Artificial Delay to help consistency
                setTimeout(() => {
                    setIsPreparing(false);
                    setSuccessMsg('Hesabınız hazır! Şimdi giriş yapabilirsiniz.');
                    setIsLogin(true);
                    setPassword('');
                }, 2500);

            } else {
                setError(result.message);
            }
        }
    } catch (err) {
        setError("Bir hata oluştu. Lütfen bağlantınızı kontrol edin.");
    } finally {
        if (!isPreparing) {
           setIsLoading(false);
        }
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-xl overflow-hidden">
        <div className="bg-slate-900 p-8 text-center relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-br from-blue-600/20 to-purple-600/20 z-0"></div>
            <div className="relative z-10 flex justify-center mb-4">
                <div className="bg-white/10 p-3 rounded-xl backdrop-blur-sm border border-white/20">
                    <Database className="w-10 h-10 text-blue-400" />
                </div>
            </div>
            <h1 className="relative z-10 text-2xl font-bold text-white mb-2">BetData Analyze Pro</h1>
            <p className="relative z-10 text-slate-400 text-sm">Profesyonel Bahis Analiz Platformu</p>
        </div>

        <div className="p-8">
            {/* Toggle Tabs */}
            <div className="flex bg-gray-100 p-1 rounded-lg mb-8">
                <button
                    onClick={() => { if(!isPreparing) { setIsLogin(true); setError(''); setSuccessMsg(''); } }}
                    disabled={isPreparing}
                    className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${isLogin ? 'bg-white text-slate-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    Giriş Yap
                </button>
                <button
                    onClick={() => { if(!isPreparing) { setIsLogin(false); setError(''); setSuccessMsg(''); } }}
                    disabled={isPreparing}
                    className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${!isLogin ? 'bg-white text-slate-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    Kayıt Ol
                </button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Kullanıcı Adı</label>
                    <input 
                        type="text" 
                        required
                        value={username}
                        onChange={(e) => setUsername(e.target.value)}
                        className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                        placeholder="Kullanıcı adınız"
                        disabled={isLoading || isPreparing}
                    />
                </div>
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Şifre</label>
                    <input 
                        type="password" 
                        required
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                        placeholder="••••••••"
                        disabled={isLoading || isPreparing}
                    />
                </div>

                {error && (
                    <div className="flex items-center gap-2 text-red-600 text-sm bg-red-50 p-3 rounded-lg border border-red-100">
                        <AlertCircle size={16} />
                        {error}
                    </div>
                )}

                {successMsg && (
                    <div className="flex items-center gap-2 text-green-600 text-sm bg-green-50 p-3 rounded-lg border border-green-100">
                        {isPreparing ? <Loader2 size={16} className="animate-spin" /> : <ShieldCheck size={16} />}
                        {successMsg}
                    </div>
                )}

                <button 
                    type="submit"
                    disabled={isLoading || isPreparing}
                    className={`w-full py-3 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-lg transition-colors flex items-center justify-center gap-2 shadow-lg shadow-blue-600/20 disabled:opacity-50 ${isPreparing ? 'cursor-wait' : ''}`}
                >
                    {(isLoading || isPreparing) ? <Loader2 size={18} className="animate-spin" /> : (isLogin ? <LogIn size={18} /> : <UserPlus size={18} />)}
                    {isPreparing ? 'Hesap Oluşturuluyor...' : (isLogin ? 'Giriş Yap' : 'Kayıt Ol')}
                </button>
            </form>


        </div>
      </div>
    </div>
  );
};

import { MatchData } from '../types';
import * as XLSX from 'xlsx';
import { upload } from '@vercel/blob/client';
import * as fflate from 'fflate';
import localforage from 'localforage';

const DATA_FILE_ZIP = 'main-data.zip';
const VERSION_FILE = 'version.json';

// Configure LocalForage
localforage.config({
  name: 'BetDataApp',
  storeName: 'matches'
});

export const dataService = {
  // Save Data: Zips the content, uploads it, and updates the version file
  saveData: async (data: MatchData[]): Promise<void> => {
    try {
      console.log("Sıkıştırma işlemi başlıyor...");
      const jsonString = JSON.stringify(data);

      // 1. Compress Data using fflate
      const zipData = await new Promise<Uint8Array>((resolve, reject) => {
        const bytes = fflate.strToU8(jsonString);
        fflate.zip({ 'data.json': bytes }, { level: 6 }, (err: Error | null, out: Uint8Array) => {
            if (err) reject(err);
            else resolve(out);
        });
      });

      // Cast zipData to any or BlobPart because TypeScript strictness might conflict with ArrayBufferLike types in some environments
      const zipFile = new File([zipData as any], DATA_FILE_ZIP, { type: 'application/zip' });

      console.log(`Veri sıkıştırıldı. Orijinal: ${(jsonString.length / 1024 / 1024).toFixed(2)}MB, Sıkıştırılmış: ${(zipFile.size / 1024 / 1024).toFixed(2)}MB`);

      // 2. Upload Zip
      await upload(DATA_FILE_ZIP, zipFile, {
        access: 'public',
        handleUploadUrl: '/api/data',
      });

      // 3. Upload Version File
      const newVersion = { timestamp: Date.now(), count: data.length };
      const versionFile = new File([JSON.stringify(newVersion)], VERSION_FILE, { type: 'application/json' });

      await upload(VERSION_FILE, versionFile, {
        access: 'public',
        handleUploadUrl: '/api/data',
      });

      // 4. Update local cache immediately
      await localforage.setItem('dataVersion', newVersion.timestamp);
      await localforage.setItem('matchData', data);

      console.log("Veri ve versiyon bilgisi güncellendi.");
      return;
    } catch (error) {
      console.error("Save Error:", error);
      throw new Error("Veri sıkıştırılırken veya yüklenirken hata oluştu.");
    }
  },

  // Append Data: Downloads full data, unzips, appends, zips, uploads
  appendData: async (newData: MatchData[]): Promise<void> => {
    try {
      const currentData = await dataService.getAllData();

      const startId = currentData.length > 0 ? Math.max(...currentData.map(d => d.id)) + 1 : 0;
      const preparedNewData = newData.map((item, index) => ({
          ...item,
          id: startId + index
      }));

      const combinedData = [...currentData, ...preparedNewData];
      await dataService.saveData(combinedData);
    } catch (error) {
       console.error("Append Error:", error);
       throw error;
    }
  },

  // Get All Data: Smart Fetching (Cache -> Version Check -> Download -> Unzip)
  getAllData: async (): Promise<MatchData[]> => {
    try {
      // 1. Get Server Version
      const versionRes = await fetch('/api/data?type=version', { cache: 'no-store' });
      const serverVersionData = await versionRes.json();
      const serverTimestamp = serverVersionData.timestamp || 0;

      // 2. Get Local Version
      const localTimestamp = await localforage.getItem<number>('dataVersion');

      // 3. Compare
      if (localTimestamp && localTimestamp === serverTimestamp) {
          const cachedData = await localforage.getItem<MatchData[]>('matchData');
          if (cachedData) {
              console.log("Veriler yerel önbellekten yüklendi.");
              return cachedData;
          }
      }

      console.log("Yeni veri indiriliyor...");

      // 4. Download Zip (If version mismatch or no cache)
      const response = await fetch('/api/data'); // Returns 307 Redirect to Blob URL
      if (response.status === 404) return [];

      const blob = await response.blob();
      const arrayBuffer = await blob.arrayBuffer();
      const uint8Array = new Uint8Array(arrayBuffer);

      // 5. Unzip
      const jsonString = await new Promise<string>((resolve, reject) => {
          fflate.unzip(uint8Array, (err: Error | null, unzipped: fflate.Unzipped) => {
              if (err) return reject(err);
              const fileContent = unzipped['data.json'];
              if (fileContent) {
                  resolve(fflate.strFromU8(fileContent));
              } else {
                  reject(new Error("Zip içinde data.json bulunamadı"));
              }
          });
      });

      const data = JSON.parse(jsonString);

      // 6. Update Cache
      await localforage.setItem('dataVersion', serverTimestamp);
      await localforage.setItem('matchData', data);

      console.log("Veri indirildi, açıldı ve önbelleklendi.");
      return Array.isArray(data) ? data : [];

    } catch (error) {
      console.error("Fetch/Unzip Error:", error);
      // Fallback: try to return cache even if error occurs
      const cached = await localforage.getItem<MatchData[]>('matchData');
      return cached || [];
    }
  },

  clearData: async (): Promise<void> => {
     await dataService.saveData([]);
  },

  removeDuplicates: async (): Promise<{ removedCount: number }> => {
    const allData = await dataService.getAllData();
    const uniqueMap = new Map<string, MatchData>();
    let originalCount = allData.length;

    allData.forEach(item => {
        const { id, ...rest } = item;
        const signature = JSON.stringify(rest);
        if (!uniqueMap.has(signature)) {
            uniqueMap.set(signature, item);
        }
    });

    const uniqueData = Array.from(uniqueMap.values());
    const removedCount = originalCount - uniqueData.length;

    if (removedCount > 0) {
        const reIndexedData = uniqueData.map((item, index) => ({
            ...item,
            id: index
        }));
        await dataService.saveData(reIndexedData);
    }

    return { removedCount };
  },

  exportToExcel: async (fileName: string = 'BetData_Export.xlsx'): Promise<void> => {
    const data = await dataService.getAllData();
    if (data.length === 0) return;

    const cleanData = data.map(({ id, ...rest }) => rest);
    const worksheet = XLSX.utils.json_to_sheet(cleanData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Maç Verileri");
    XLSX.writeFile(workbook, fileName);
  }
};

import { handleUpload } from '@vercel/blob/client';
import { list } from '@vercel/blob';

export const config = {
  runtime: 'nodejs',
};

const DATA_FILE_ZIP = 'main-data.zip';
const VERSION_FILE = 'version.json';

export default async function handler(request: any, response: any) {
  const token = process.env.BLOB_READ_WRITE_TOKEN;

  if (!token) {
    return response.status(500).json({ error: 'BLOB_READ_WRITE_TOKEN not configured' });
  }

  // GET: Fetch Data or Version
  if (request.method === 'GET') {
    // AGGRESSIVE CACHE BUSTING
    // This is crucial for mobile devices to prevent stale data
    response.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    response.setHeader('Pragma', 'no-cache');
    response.setHeader('Expires', '0');
    response.setHeader('Surrogate-Control', 'no-store');

    try {
        const { type } = request.query; // ?type=version or default (data)
        const { blobs } = await list({ token });

        if (type === 'version') {
            const versionBlob = blobs.find((b: any) => b.pathname === VERSION_FILE);
            if (!versionBlob) return response.status(200).json({ timestamp: 0 }); // No version yet

            // Bypass cache for version check fetch from Blob storage
            const res = await fetch(versionBlob.url, { cache: 'no-store' });
            const data = await res.json();
            return response.status(200).json(data);
        } 
        else {
            // Get the ZIP file URL
            const dataBlob = blobs.find((b: any) => b.pathname === DATA_FILE_ZIP);
            if (!dataBlob) return response.status(404).json({ error: 'Data not found' });

            // Redirect to the blob URL
            // Even though we redirect, the headers set above apply to this 307 response
            return response.redirect(dataBlob.url);
        }

    } catch (e: any) {
        return response.status(500).json({ error: e.message || 'Unknown error' });
    }
  }

  // POST: Generate a client upload token
  if (request.method === 'POST') {
    const body = request.body;

    try {
      const jsonResponse = await handleUpload({
        body,
        request,
        onBeforeGenerateToken: async (pathname) => {
          // Allow both the zip file and the version file
          if (pathname !== DATA_FILE_ZIP && pathname !== VERSION_FILE) {
            throw new Error('Invalid filename. Only main-data.zip and version.json allowed.');
          }
          return {
            allowedContentTypes: ['application/zip', 'application/json', 'application/x-zip-compressed'],
            tokenPayload: JSON.stringify({
              userId: 'admin',
            }),
          };
        },
        onUploadCompleted: async ({ blob, tokenPayload }) => {
          console.log('Blob upload completed', blob.pathname);
        },
      });

      return response.status(200).json(jsonResponse);
    } catch (error: any) {
      return response.status(400).json({ error: error.message || 'Upload failed' });
    }
  }

  return response.status(405).json({ error: 'Method not allowed' });
}

import { MatchData } from '../types';
import * as XLSX from 'xlsx';
import { upload } from '@vercel/blob/client';
import * as fflate from 'fflate';
import localforage from 'localforage';

const DATA_FILE_ZIP = 'main-data.zip';
const VERSION_FILE = 'version.json';

// Configure LocalForage
localforage.config({
  name: 'BetDataApp',
  storeName: 'matches'
});

export const dataService = {
  // Save Data: Zips the content, uploads it, and updates the version file
  saveData: async (data: MatchData[]): Promise<void> => {
    try {
      console.log("Sıkıştırma işlemi başlıyor...");
      const jsonString = JSON.stringify(data);

      // 1. Compress Data using fflate
      const zipData = await new Promise<Uint8Array>((resolve, reject) => {
        const bytes = fflate.strToU8(jsonString);
        fflate.zip({ 'data.json': bytes }, { level: 6 }, (err: Error | null, out: Uint8Array) => {
            if (err) reject(err);
            else resolve(out);
        });
      });

      // Cast zipData to any or BlobPart because TypeScript strictness might conflict with ArrayBufferLike types in some environments
      const zipFile = new File([zipData as any], DATA_FILE_ZIP, { type: 'application/zip' });

      console.log(`Veri sıkıştırıldı. Orijinal: ${(jsonString.length / 1024 / 1024).toFixed(2)}MB, Sıkıştırılmış: ${(zipFile.size / 1024 / 1024).toFixed(2)}MB`);

      // 2. Upload Zip
      await upload(DATA_FILE_ZIP, zipFile, {
        access: 'public',
        handleUploadUrl: '/api/data',
      });

      // 3. Upload Version File
      const newVersion = { timestamp: Date.now(), count: data.length };
      const versionFile = new File([JSON.stringify(newVersion)], VERSION_FILE, { type: 'application/json' });

      await upload(VERSION_FILE, versionFile, {
        access: 'public',
        handleUploadUrl: '/api/data',
      });

      // 4. Update local cache immediately
      await localforage.setItem('dataVersion', newVersion.timestamp);
      await localforage.setItem('matchData', data);

      console.log("Veri ve versiyon bilgisi güncellendi.");
      return;
    } catch (error) {
      console.error("Save Error:", error);
      throw new Error("Veri sıkıştırılırken veya yüklenirken hata oluştu.");
    }
  },

  // Append Data: Downloads full data, unzips, appends, zips, uploads
  appendData: async (newData: MatchData[]): Promise<void> => {
    try {
      const currentData = await dataService.getAllData();

      const startId = currentData.length > 0 ? Math.max(...currentData.map(d => d.id)) + 1 : 0;
      const preparedNewData = newData.map((item, index) => ({
          ...item,
          id: startId + index
      }));

      const combinedData = [...currentData, ...preparedNewData];
      await dataService.saveData(combinedData);
    } catch (error) {
       console.error("Append Error:", error);
       throw error;
    }
  },

  // Get All Data: Smart Fetching (Cache -> Version Check -> Download -> Unzip)
  getAllData: async (): Promise<MatchData[]> => {
    try {
      const timestamp = Date.now();

      // 1. Get Server Version - Add timestamp to force bypass cache
      const versionRes = await fetch(`/api/data?type=version&_t=${timestamp}`, { 
          cache: 'no-store',
          headers: { 'Pragma': 'no-cache', 'Cache-Control': 'no-cache' }
      });
      const serverVersionData = await versionRes.json();
      const serverTimestamp = serverVersionData.timestamp || 0;

      // 2. Get Local Version
      const localTimestamp = await localforage.getItem<number>('dataVersion');

      // 3. Compare
      if (localTimestamp && localTimestamp === serverTimestamp) {
          const cachedData = await localforage.getItem<MatchData[]>('matchData');
          if (cachedData) {
              console.log("Veriler yerel önbellekten yüklendi (Versiyon eşleşti).");
              return cachedData;
          }
      }

      console.log("Yeni veri indiriliyor... Sunucu Zamanı:", serverTimestamp);

      // 4. Download Zip - Add timestamp to force bypass cache
      const response = await fetch(`/api/data?_t=${timestamp}`, {
          cache: 'no-store',
          headers: { 'Pragma': 'no-cache', 'Cache-Control': 'no-cache' }
      });

      if (response.status === 404) return [];

      const blob = await response.blob();
      const arrayBuffer = await blob.arrayBuffer();
      const uint8Array = new Uint8Array(arrayBuffer);

      // 5. Unzip
      const jsonString = await new Promise<string>((resolve, reject) => {
          fflate.unzip(uint8Array, (err: Error | null, unzipped: fflate.Unzipped) => {
              if (err) return reject(err);
              const fileContent = unzipped['data.json'];
              if (fileContent) {
                  resolve(fflate.strFromU8(fileContent));
              } else {
                  reject(new Error("Zip içinde data.json bulunamadı"));
              }
          });
      });

      const data = JSON.parse(jsonString);

      // 6. Update Cache
      await localforage.setItem('dataVersion', serverTimestamp);
      await localforage.setItem('matchData', data);

      console.log("Veri indirildi, açıldı ve önbelleklendi.");
      return Array.isArray(data) ? data : [];

    } catch (error) {
      console.error("Fetch/Unzip Error:", error);
      // Fallback: try to return cache even if error occurs
      const cached = await localforage.getItem<MatchData[]>('matchData');
      return cached || [];
    }
  },

  clearData: async (): Promise<void> => {
     await dataService.saveData([]);
  },

  removeDuplicates: async (): Promise<{ removedCount: number }> => {
    const allData = await dataService.getAllData();
    const uniqueMap = new Map<string, MatchData>();
    let originalCount = allData.length;

    allData.forEach(item => {
        const { id, ...rest } = item;
        const signature = JSON.stringify(rest);
        if (!uniqueMap.has(signature)) {
            uniqueMap.set(signature, item);
        }
    });

    const uniqueData = Array.from(uniqueMap.values());
    const removedCount = originalCount - uniqueData.length;

    if (removedCount > 0) {
        const reIndexedData = uniqueData.map((item, index) => ({
            ...item,
            id: index
        }));
        await dataService.saveData(reIndexedData);
    }

    return { removedCount };
  },

  exportToExcel: async (fileName: string = 'BetData_Export.xlsx'): Promise<void> => {
    const data = await dataService.getAllData();
    if (data.length === 0) return;

    const cleanData = data.map(({ id, ...rest }) => rest);
    const worksheet = XLSX.utils.json_to_sheet(cleanData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Maç Verileri");
    XLSX.writeFile(workbook, fileName);
  }
};

import { User } from '../types';

const SESSION_KEY = 'betdata_user_session';

export const authService = {
  // Load user from local storage on app start
  getCurrentUser: (): User | null => {
    try {
      const storedUser = localStorage.getItem(SESSION_KEY);
      if (storedUser) {
        return JSON.parse(storedUser);
      }
      return null;
    } catch (e) {
      return null;
    }
  },

  // Fetch users from API (Force fresh data)
  getUsers: async (): Promise<User[]> => {
    try {
      // Add timestamp to prevent browser caching
      const res = await fetch(`/api/users?t=${Date.now()}`, {
        headers: { 
            'Cache-Control': 'no-cache',
            'Pragma': 'no-cache'
        }
      });
      if (!res.ok) return [];
      return await res.json();
    } catch (e) {
      console.error("Error fetching users:", e);
      return [];
    }
  },

  register: async (username: string, password: string): Promise<{ success: boolean; message: string; user?: User }> => {
    // We do NOT fetch all users here anymore. We let the server handle the check.
    const newUser: User = {
      username,
      password,
      role: 'free'
    };

    try {
        const res = await fetch('/api/users', {
            method: 'POST',
            body: JSON.stringify({
                action: 'register',
                user: newUser
            }),
            headers: { 'Content-Type': 'application/json' }
        });

        const data = await res.json();

        if (res.ok && data.success) {
            return { success: true, message: 'Kayıt başarılı.', user: newUser };
        } else {
            return { success: false, message: data.message || 'Kayıt başarısız.' };
        }
    } catch (e) {
        return { success: false, message: 'Sunucu hatası.' };
    }
  },

  login: async (username: string, password: string): Promise<{ success: boolean; message: string; user?: User }> => {
    // For login, we still fetch the list to check credentials client-side for simplicity,
    // but relying on getUsers() which now forces a fresh fetch.
    const users = await authService.getUsers();
    const user = users.find(u => u.username === username && u.password === password);

    if (!user) {
      return { success: false, message: 'Kullanıcı adı veya şifre hatalı.' };
    }

    if (user.role === 'banned') {
      return { success: false, message: 'Bu hesap yasaklanmıştır. Yönetici ile iletişime geçin.' };
    }

    // Check expiration logic
    if (user.role === 'premium' && user.premiumExpiresAt && Date.now() > user.premiumExpiresAt) {
        // Update user on server
        const updatedUser = { ...user, role: 'free' as const, premiumExpiresAt: undefined };
        await authService.updateUser(updatedUser);

        // Save updated session
        localStorage.setItem(SESSION_KEY, JSON.stringify(updatedUser));
        return { success: true, message: 'Premium süreniz doldu, ücretsiz plana geçirildiniz.', user: updatedUser };
    }

    // Save Session
    localStorage.setItem(SESSION_KEY, JSON.stringify(user));

    return { success: true, message: 'Giriş başarılı.', user };
  },

  logout: () => {
    localStorage.removeItem(SESSION_KEY);
  },

  updateUser: async (updatedUser: User): Promise<boolean> => {
    try {
      const res = await fetch('/api/users', {
          method: 'POST',
          body: JSON.stringify({
              action: 'update',
              user: updatedUser
          }),
          headers: { 'Content-Type': 'application/json' }
      });
      const data = await res.json();
      return data.success;
    } catch (e) {
        console.error("Update error:", e);
        return false;
    }
  },

  deleteUser: async (username: string): Promise<boolean> => {
    try {
        const res = await fetch('/api/users', {
            method: 'POST',
            body: JSON.stringify({
                action: 'delete',
                username: username
            }),
            headers: { 'Content-Type': 'application/json' }
        });
        const data = await res.json();
        return data.success;
    } catch (e) {
        console.error("Delete error:", e);
        return false;
    }
  },

  addPremiumTime: async (username: string, durationMinutes: number) => {
    const users = await authService.getUsers();
    const user = users.find(u => u.username === username);

    if (user) {
        const now = Date.now();
        const startTime = (user.role === 'premium' && user.premiumExpiresAt && user.premiumExpiresAt > now) 
            ? user.premiumExpiresAt 
            : now;

        user.role = 'premium';
        user.premiumExpiresAt = startTime + (durationMinutes * 60 * 1000);

        await authService.updateUser(user);
    }
  }
};

