import { handleUpload } from '@vercel/blob/client';
import { list } from '@vercel/blob';

export const config = {
  runtime: 'nodejs',
};

const DATA_FILE_ZIP = 'main-data.zip';
const VERSION_FILE = 'version.json';

export default async function handler(request: any, response: any) {
  const token = process.env.BLOB_READ_WRITE_TOKEN;

  if (!token) {
    return response.status(500).json({ error: 'BLOB_READ_WRITE_TOKEN not configured' });
  }

  // GET: Fetch Data or Version
  if (request.method === 'GET') {
    // AGGRESSIVE CACHE BUSTING HEADERS
    response.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    response.setHeader('Pragma', 'no-cache');
    response.setHeader('Expires', '0');
    response.setHeader('Surrogate-Control', 'no-store');

    try {
        const { type } = request.query; // ?type=version or default (data)
        // Always fetch fresh list from Vercel Blob
        const { blobs } = await list({ token });

        if (type === 'version') {
            const versionBlob = blobs.find((b: any) => b.pathname === VERSION_FILE);
            if (!versionBlob) return response.status(200).json({ timestamp: 0 }); // No version yet

            // Bypass server-side fetch cache
            const res = await fetch(versionBlob.url, { cache: 'no-store' });
            const data = await res.json();
            return response.status(200).json(data);
        } 
        else {
            // Get the ZIP file URL
            const dataBlob = blobs.find((b: any) => b.pathname === DATA_FILE_ZIP);
            if (!dataBlob) return response.status(404).json({ error: 'Data not found' });

            // CRITICAL FIX FOR MOBILE:
            // Append a random query parameter to the BLOB URL itself.
            // This forces the browser to treat the redirect target as a new resource,
            // bypassing the browser's aggressive cache of the static file.
            const cacheBustUrl = `${dataBlob.url}?cb=${Date.now()}`;

            return response.redirect(cacheBustUrl);
        }

    } catch (e: any) {
        return response.status(500).json({ error: e.message || 'Unknown error' });
    }
  }

  // POST: Generate a client upload token
  if (request.method === 'POST') {
    const body = request.body;

    try {
      const jsonResponse = await handleUpload({
        body,
        request,
        onBeforeGenerateToken: async (pathname) => {
          // Allow both the zip file and the version file
          if (pathname !== DATA_FILE_ZIP && pathname !== VERSION_FILE) {
            throw new Error('Invalid filename. Only main-data.zip and version.json allowed.');
          }
          return {
            allowedContentTypes: ['application/zip', 'application/json', 'application/x-zip-compressed'],
            tokenPayload: JSON.stringify({
              userId: 'admin',
            }),
          };
        },
        onUploadCompleted: async ({ blob, tokenPayload }) => {
          console.log('Blob upload completed', blob.pathname);
        },
      });

      return response.status(200).json(jsonResponse);
    } catch (error: any) {
      return response.status(400).json({ error: error.message || 'Upload failed' });
    }
  }

  return response.status(405).json({ error: 'Method not allowed' });
}

import { MatchData } from '../types';
import * as XLSX from 'xlsx';
import { upload } from '@vercel/blob/client';
import * as fflate from 'fflate';
import localforage from 'localforage';

const DATA_FILE_ZIP = 'main-data.zip';
const VERSION_FILE = 'version.json';

// Configure LocalForage
localforage.config({
  name: 'BetDataApp',
  storeName: 'matches'
});

export const dataService = {
  // Save Data: Zips the content, uploads it, and updates the version file
  saveData: async (data: MatchData[]): Promise<void> => {
    try {
      console.log("Sıkıştırma işlemi başlıyor...");
      const jsonString = JSON.stringify(data);

      // 1. Compress Data using fflate
      const zipData = await new Promise<Uint8Array>((resolve, reject) => {
        const bytes = fflate.strToU8(jsonString);
        fflate.zip({ 'data.json': bytes }, { level: 6 }, (err: Error | null, out: Uint8Array) => {
            if (err) reject(err);
            else resolve(out);
        });
      });

      // Cast zipData to any or BlobPart because TypeScript strictness might conflict with ArrayBufferLike types in some environments
      const zipFile = new File([zipData as any], DATA_FILE_ZIP, { type: 'application/zip' });

      console.log(`Veri sıkıştırıldı. Orijinal: ${(jsonString.length / 1024 / 1024).toFixed(2)}MB, Sıkıştırılmış: ${(zipFile.size / 1024 / 1024).toFixed(2)}MB`);

      // 2. Upload Zip
      await upload(DATA_FILE_ZIP, zipFile, {
        access: 'public',
        handleUploadUrl: '/api/data',
      });

      // 3. Upload Version File
      const newVersion = { timestamp: Date.now(), count: data.length };
      const versionFile = new File([JSON.stringify(newVersion)], VERSION_FILE, { type: 'application/json' });

      await upload(VERSION_FILE, versionFile, {
        access: 'public',
        handleUploadUrl: '/api/data',
      });

      // 4. Update local cache immediately
      // CLEAR old data first to avoid corruption or memory issues
      await localforage.clear(); 
      await localforage.setItem('dataVersion', newVersion.timestamp);
      await localforage.setItem('matchData', data);

      console.log("Veri ve versiyon bilgisi güncellendi.");
      return;
    } catch (error) {
      console.error("Save Error:", error);
      throw new Error("Veri sıkıştırılırken veya yüklenirken hata oluştu.");
    }
  },

  // Append Data: Downloads full data, unzips, appends, zips, uploads
  appendData: async (newData: MatchData[]): Promise<void> => {
    try {
      const currentData = await dataService.getAllData();

      const startId = currentData.length > 0 ? Math.max(...currentData.map(d => d.id)) + 1 : 0;
      const preparedNewData = newData.map((item, index) => ({
          ...item,
          id: startId + index
      }));

      const combinedData = [...currentData, ...preparedNewData];
      await dataService.saveData(combinedData);
    } catch (error) {
       console.error("Append Error:", error);
       throw error;
    }
  },

  // Get All Data: Smart Fetching (Cache -> Version Check -> Download -> Unzip)
  // forceUpdate: Skips cache check and downloads fresh data
  getAllData: async (forceUpdate: boolean = false): Promise<MatchData[]> => {
    try {
      const timestamp = Date.now();

      // 1. Get Server Version
      const versionRes = await fetch(`/api/data?type=version&_t=${timestamp}`, { 
          cache: 'no-store',
          headers: { 'Pragma': 'no-cache', 'Cache-Control': 'no-cache' }
      });
      const serverVersionData = await versionRes.json();
      const serverTimestamp = serverVersionData.timestamp || 0;

      // 2. Check Local Cache (Only if NOT forced)
      if (!forceUpdate) {
          const localTimestamp = await localforage.getItem<number>('dataVersion');
          if (localTimestamp && localTimestamp === serverTimestamp) {
              const cachedData = await localforage.getItem<MatchData[]>('matchData');
              if (cachedData) {
                  console.log("Veriler yerel önbellekten yüklendi (Versiyon eşleşti).");
                  return cachedData;
              }
          }
      }

      console.log(forceUpdate ? "Zorla güncelleme istendi." : "Yeni veri indiriliyor...", "Sunucu Zamanı:", serverTimestamp);

      // 3. Download Zip - Add timestamp to force bypass cache
      const response = await fetch(`/api/data?_t=${timestamp}`, {
          cache: 'no-store',
          headers: { 'Pragma': 'no-cache', 'Cache-Control': 'no-cache' }
      });

      if (response.status === 404) return [];

      const blob = await response.blob();
      const arrayBuffer = await blob.arrayBuffer();
      const uint8Array = new Uint8Array(arrayBuffer);

      // 4. Unzip
      const jsonString = await new Promise<string>((resolve, reject) => {
          fflate.unzip(uint8Array, (err: Error | null, unzipped: fflate.Unzipped) => {
              if (err) return reject(err);
              const fileContent = unzipped['data.json'];
              if (fileContent) {
                  resolve(fflate.strFromU8(fileContent));
              } else {
                  reject(new Error("Zip içinde data.json bulunamadı"));
              }
          });
      });

      const data = JSON.parse(jsonString);

      // 5. Update Cache (Clear first)
      await localforage.clear();
      await localforage.setItem('dataVersion', serverTimestamp);
      await localforage.setItem('matchData', data);

      console.log("Veri indirildi, açıldı ve önbelleklendi.");
      return Array.isArray(data) ? data : [];

    } catch (error) {
      console.error("Fetch/Unzip Error:", error);
      // Fallback: try to return cache even if error occurs, unless forced
      if (!forceUpdate) {
        const cached = await localforage.getItem<MatchData[]>('matchData');
        return cached || [];
      }
      throw error;
    }
  },

  clearData: async (): Promise<void> => {
     await dataService.saveData([]);
  },

  removeDuplicates: async (): Promise<{ removedCount: number }> => {
    const allData = await dataService.getAllData();
    const uniqueMap = new Map<string, MatchData>();
    let originalCount = allData.length;

    allData.forEach(item => {
        const { id, ...rest } = item;
        const signature = JSON.stringify(rest);
        if (!uniqueMap.has(signature)) {
            uniqueMap.set(signature, item);
        }
    });

    const uniqueData = Array.from(uniqueMap.values());
    const removedCount = originalCount - uniqueData.length;

    if (removedCount > 0) {
        const reIndexedData = uniqueData.map((item, index) => ({
            ...item,
            id: index
        }));
        await dataService.saveData(reIndexedData);
    }

    return { removedCount };
  },

  exportToExcel: async (fileName: string = 'BetData_Export.xlsx'): Promise<void> => {
    const data = await dataService.getAllData();
    if (data.length === 0) return;

    const cleanData = data.map(({ id, ...rest }) => rest);
    const worksheet = XLSX.utils.json_to_sheet(cleanData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Maç Verileri");
    XLSX.writeFile(workbook, fileName);
  }
};

import React, { useState, useMemo, useEffect } from 'react';
import { FileUpload } from './components/FileUpload';
import { VirtualTable } from './components/VirtualTable';
import { Auth } from './components/Auth';
import { UpgradeAlert } from './components/UpgradeAlert';
import { AdminPanel } from './components/AdminPanel';
import { ManualEntryModal } from './components/ManualEntryModal';
import { parseExcelFile } from './utils/excelParser';
import { MatchData, User } from './types';
import { authService } from './services/authService';
import { dataService } from './services/dataService';
import { Database, AlertCircle, LogOut, Crown, Shield, Clock, Loader2, CopyPlus, Eraser, FilePlus2, Trash2, PenLine, X, Download, Cloud, PlayCircle, RefreshCw, Zap } from 'lucide-react';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [masterData, setMasterData] = useState<MatchData[]>([]);

  // Loading States
  const [isInitializing, setIsInitializing] = useState(true); // App Startup
  const [isLoading, setIsLoading] = useState(false); // Manual Actions
  const [isDataLoaded, setIsDataLoaded] = useState(false); // Valid Data Present

  const [error, setError] = useState<string | null>(null);

  // Admin Options
  const [isAppendMode, setIsAppendMode] = useState(false);
  const [isManualModalOpen, setIsManualModalOpen] = useState(false);
  const [showClearConfirm, setShowClearConfirm] = useState(false);

  // State for timer
  const [now, setNow] = useState(Date.now());

  // 1. Initialize Session on Mount
  useEffect(() => {
     const initApp = async () => {
         const savedUser = authService.getCurrentUser();
         if (savedUser) {
             setUser(savedUser);
             // If we have a user, immediately try to load/sync data
             await performSmartDataSync();
         }
         setIsInitializing(false);
     };

     initApp();

     const interval = setInterval(() => {
         setNow(Date.now());
     }, 1000);
     return () => clearInterval(interval);
  }, []);

  // Helper for Smart Data Sync
  // force: true ignores version check and forces download
  const performSmartDataSync = async (force: boolean = false) => {
      setIsLoading(true);
      setError(null);
      try {
          // dataService.getAllData already handles the "Check Version -> Load DB or Download" logic
          const savedData = await dataService.getAllData(force);
          if (savedData && savedData.length > 0) {
            setMasterData(savedData);
            setIsDataLoaded(true);
          } else {
             setIsDataLoaded(false);
          }
      } catch (err) {
          console.error("Auto-sync error:", err);
          if (force) {
            setError("Veri güncellenemedi. İnternet bağlantınızı kontrol edin.");
          }
      } finally {
          setIsLoading(false);
      }
  };

  const handleLogin = (userData: User) => {
    setUser(userData);
    setIsDataLoaded(false); 
    setMasterData([]);
    // Trigger sync after login
    performSmartDataSync();
  };

  const handleLogout = () => {
    authService.logout();
    setUser(null);
    setMasterData([]);
    setIsDataLoaded(false);
  };

  // Manual Trigger (Re-check version)
  const handleLoadData = async () => {
      // FORCE update when clicking "Retry" or "Refresh"
      await performSmartDataSync(true);
  };

  const handleFileUpload = async (file: File) => {
    setIsLoading(true);
    setError(null);
    try {
        const parsedData = await parseExcelFile(file);

        if (isAppendMode) {
            if (!isDataLoaded && masterData.length === 0) {
               try {
                  const currentData = await dataService.getAllData();
                  const startId = currentData.length > 0 ? Math.max(...currentData.map(d => d.id)) + 1 : 0;
                  const preparedNewData = parsedData.map((item, index) => ({ ...item, id: startId + index }));
                  const combinedData = [...currentData, ...preparedNewData];
                  await dataService.saveData(combinedData);
                  setMasterData(combinedData);
               } catch(e) { throw e; }
            } else {
               await dataService.appendData(parsedData);
               const allData = await dataService.getAllData(true); // Force sync after append
               setMasterData(allData);
            }
            alert(`${parsedData.length} satır başarıyla eklendi ve buluta kaydedildi.`);
        } else {
            await dataService.saveData(parsedData);
            setMasterData(parsedData);
            alert("Veriler başarıyla buluta yüklendi.");
        }
        setIsDataLoaded(true);
    } catch (err) {
        console.error(err);
        setError("Dosya işlenirken veya sunucuya yüklenirken hata oluştu.");
    } finally {
        setIsLoading(false);
    }
  };

  const confirmClear = async () => {
    setShowClearConfirm(false);
    setIsLoading(true);
    try {
      await dataService.clearData();
      setMasterData([]);
      setIsDataLoaded(false);
      setError(null);
    } catch (e) {
      setError("Veriler silinirken hata oluştu.");
    } finally {
        setIsLoading(false);
    }
  };

  const handleManualAdd = async (newData: MatchData) => {
      setIsLoading(true);
      try {
          await dataService.appendData([newData]);
          const freshData = await dataService.getAllData(true);
          setMasterData(freshData);
          setIsManualModalOpen(false);
          alert("Kayıt başarıyla eklendi.");
          setIsDataLoaded(true);
      } catch(e) {
          console.error(e);
          setError("Manuel kayıt eklenirken hata oluştu.");
      } finally {
          setIsLoading(false);
      }
  };

  const handleRemoveDuplicates = async () => {
      setIsLoading(true);
      try {
          const result = await dataService.removeDuplicates();
          if (result.removedCount > 0) {
              const freshData = await dataService.getAllData(true);
              setMasterData(freshData);
              alert(`İşlem tamamlandı: ${result.removedCount} adet yinelenen satır silindi.`);
          } else {
              alert("Yinelenen veri bulunamadı.");
          }
      } catch (e) {
          console.error(e);
          setError("Yinelenen veriler silinirken hata oluştu.");
      } finally {
          setIsLoading(false);
      }
  };

  const handleExport = async () => {
      let dataToExport = masterData;
      if (!isDataLoaded || masterData.length === 0) {
         setIsLoading(true);
         try {
            dataToExport = await dataService.getAllData();
            setMasterData(dataToExport);
            setIsDataLoaded(true);
         } catch(e) {
             alert("Veri indirilemedi.");
             setIsLoading(false);
             return;
         }
         setIsLoading(false);
      }

      if (dataToExport.length === 0) {
          alert("Dışa aktarılacak veri yok.");
          return;
      }

      try {
          await dataService.exportToExcel();
      } catch (e) {
          console.error(e);
          alert("Dışa aktarma başarısız.");
      }
  };

  const displayedData = useMemo(() => {
    if (!user) return [];
    if (user.role === 'admin' || user.role === 'premium') {
        return masterData;
    }
    return masterData.slice(0, 50);
