            if (err) return reject(err);

            // KRİTİK DÜZELTME: 'out' verisini [out] şeklinde diziye alarak 
            // TS2322 'BlobPart' hatasını çözüyoruz
            const blob = new Blob([out], { type: 'application/octet-stream' });
            resolve(blob);
        });
    });
};

// ZİPLİ VERİYİ AÇMA (Kullanıcı Tarafı)
const unzipData = async (compressedData: Uint8Array): Promise<any[]> => {
    return new Promise((resolve, reject) => {
        // Gelen veriyi çözüyoruz
        fflate.unzlib(compressedData, (err: Error | null, unzipped: Uint8Array) => {
            if (err) return reject(err);

            const decoded = new TextDecoder().decode(unzipped);
            resolve(JSON.parse(decoded));
        });
    });
};

