import { MatchData } from '../types';
import * as XLSX from 'xlsx';
import { upload } from '@vercel/blob/client';
import * as fflate from 'fflate';
import localforage from 'localforage';

// Configure LocalForage
localforage.config({
  name: 'BetDataApp',
  storeName: 'matches'
});

export const dataService = {
  // Save Data: Zips content with a timestamped filename and uploads it
  saveData: async (data: MatchData[]): Promise<void> => {
    try {
      console.log("Veri sıkıştırılıyor...");

      // Use TextEncoder for reliable UTF-8 encoding
      const jsonString = JSON.stringify(data);
      const buf = new TextEncoder().encode(jsonString);

      // 1. Compress Data using fflate.zip (Compatible with standard ZIP tools)
      const zipData = await new Promise<Uint8Array>((resolve, reject) => {
        // data.json is the internal file name inside the zip
        fflate.zip({ 'data.json': buf }, { level: 6 }, (err: Error | null, out: Uint8Array) => {
            if (err) return reject(err);
            resolve(out);
        });
      });

      // 2. Generate Dynamic Filename (data_v{TIMESTAMP}.zip)
      const timestamp = Date.now();
      const filename = `data_v${timestamp}.zip`;

      // TS FIX: Cast zipData to 'any' to bypass strict BlobPart type mismatch (Uint8Array vs BlobPart)
      const zipFile = new File([zipData as any], filename, { type: 'application/zip' });

      console.log(`Yükleniyor: ${filename} (${(zipFile.size / 1024 / 1024).toFixed(2)}MB)`);

      // 3. Upload to Vercel Blob
      await upload(filename, zipFile, {
        access: 'public',
        handleUploadUrl: '/api/data',
      });

      // 4. Update Local Cache Immediately
      await localforage.clear(); 
      await localforage.setItem('dataVersion', timestamp);
      await localforage.setItem('matchData', data);

      console.log("Yükleme ve önbellekleme tamamlandı.");
      return;
    } catch (error) {
      console.error("Save Error:", error);
      throw new Error("Veri sıkıştırılırken veya yüklenirken hata oluştu.");
    }
  },

  appendData: async (newData: MatchData[]): Promise<void> => {
    try {
      const currentData = await dataService.getAllData();

      const startId = currentData.length > 0 ? Math.max(...currentData.map(d => d.id)) + 1 : 0;
      const preparedNewData = newData.map((item, index) => ({
          ...item,
          id: startId + index
      }));

      const combinedData = [...currentData, ...preparedNewData];
      await dataService.saveData(combinedData);
    } catch (error) {
       console.error("Append Error:", error);
       throw error;
    }
  },

  // Get All Data: Checks version, if new version exists on server, deletes local DB and fetches new one
  getAllData: async (forceUpdate: boolean = false): Promise<MatchData[]> => {
    try {
      const clientTimestamp = Date.now();

      // 1. Get Server Version (Dynamic)
      const versionRes = await fetch(`/api/data?type=version&_t=${clientTimestamp}`, { 
          cache: 'no-store',
          headers: { 'Pragma': 'no-cache', 'Cache-Control': 'no-cache' }
      });

      if (!versionRes.ok) return [];

      const serverData = await versionRes.json();
      const serverVersion = serverData.timestamp || 0;

      // 2. Check Local Cache (Only if NOT forced)
      if (!forceUpdate) {
          const localVersion = await localforage.getItem<number>('dataVersion');
          if (localVersion && localVersion === serverVersion) {
              const cachedData = await localforage.getItem<MatchData[]>('matchData');
              if (cachedData) {
                  console.log("Güncel veri önbellekten yüklendi.");
                  return cachedData;
              }
          }
      }

      console.log(forceUpdate ? "Zorla güncelleme yapılıyor." : "Yeni versiyon bulundu, indiriliyor...", serverVersion);

      // 3. Download Latest Zip
      const response = await fetch(`/api/data?_t=${clientTimestamp}`, {
          cache: 'no-store',
          headers: { 'Pragma': 'no-cache', 'Cache-Control': 'no-cache' }
      });

      if (response.status === 404) return [];

      const blob = await response.blob();
      const arrayBuffer = await blob.arrayBuffer();
      const uint8Array = new Uint8Array(arrayBuffer);

      // 4. Unzip (Typed strictly)
      const jsonString = await new Promise<string>((resolve, reject) => {
          fflate.unzip(uint8Array, (err: Error | null, unzipped: fflate.Unzipped) => {
              if (err) return reject(err);

              const fileContent = unzipped['data.json'];
              if (fileContent) {
                  // Use TextDecoder for reliable decoding
                  const decoded = new TextDecoder().decode(fileContent);
                  resolve(decoded);
              } else {
                  reject(new Error("Zip arşivi bozuk veya data.json eksik."));
              }
          });
      });

      const data = JSON.parse(jsonString);

      // 5. Update Cache (Critical: Clear first)
      await localforage.clear();
      await localforage.setItem('dataVersion', serverVersion);
      await localforage.setItem('matchData', data);

      console.log("Veri güncellendi.");
      return Array.isArray(data) ? data : [];

    } catch (error) {
      console.error("Veri Çekme Hatası:", error);

      // Fallback: If network fails, try to return whatever is in cache
      if (!forceUpdate) {
        const cached = await localforage.getItem<MatchData[]>('matchData');
        return cached || [];
      }
      throw error;
    }
  },

  clearData: async (): Promise<void> => {
     await dataService.saveData([]);
  },

  removeDuplicates: async (): Promise<{ removedCount: number }> => {
    const allData = await dataService.getAllData();
    const uniqueMap = new Map<string, MatchData>();
    let originalCount = allData.length;

    allData.forEach(item => {
        const { id, ...rest } = item;
        const signature = JSON.stringify(rest);
        if (!uniqueMap.has(signature)) {
            uniqueMap.set(signature, item);
        }
    });

    const uniqueData = Array.from(uniqueMap.values());
    const removedCount = originalCount - uniqueData.length;

    if (removedCount > 0) {
        const reIndexedData = uniqueData.map((item, index) => ({
            ...item,
            id: index
        }));
        await dataService.saveData(reIndexedData);
    }

    return { removedCount };
  },

  exportToExcel: async (fileName: string = 'BetData_Export.xlsx'): Promise<void> => {
    const data = await dataService.getAllData();
    if (data.length === 0) return;

    const cleanData = data.map(({ id, ...rest }) => rest);
    const worksheet = XLSX.utils.json_to_sheet(cleanData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Maç Verileri");
    XLSX.writeFile(workbook, fileName);
  }
};

import { handleUpload } from '@vercel/blob/client';
import { list, del } from '@vercel/blob';

export const config = {
  runtime: 'nodejs',
};

// We now look for files matching this pattern prefix
const DATA_FILE_PREFIX = 'data_v';

export default async function handler(request: any, response: any) {
  const token = process.env.BLOB_READ_WRITE_TOKEN;

  if (!token) {
    return response.status(500).json({ error: 'BLOB_READ_WRITE_TOKEN not configured' });
  }

  // GET: Find latest data, return version or redirect to file
  if (request.method === 'GET') {
    // 1. HEADERS: Force no-cache everywhere
    response.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    response.setHeader('Pragma', 'no-cache');
    response.setHeader('Expires', '0');
    response.setHeader('Surrogate-Control', 'no-store');

    try {
        const { type } = request.query;

        // 2. LIST: Get all blobs to find the latest version
        const { blobs } = await list({ token });

        // Filter for our data files: data_v{timestamp}.zip
        // Sort by uploadedAt (descending) -> Newest first
        const dataFiles = blobs
            .filter((b: any) => b.pathname.startsWith(DATA_FILE_PREFIX) && b.pathname.endsWith('.zip'))
            .sort((a: any, b: any) => new Date(b.uploadedAt).getTime() - new Date(a.uploadedAt).getTime());

        const latestFile = dataFiles[0];

        // 3. CLEANUP: Delete old files asynchronously to save storage
        // We keep the latest one, delete the rest.
        if (dataFiles.length > 1) {
            const filesToDelete = dataFiles.slice(1).map((b: any) => b.url);
            // Fire and forget delete
            if (filesToDelete.length > 0) {
                 del(filesToDelete, { token }).catch(console.error);
            }
        }

        // Handle: No data exists yet
        if (!latestFile) {
            if (type === 'version') return response.status(200).json({ timestamp: 0 });
            return response.status(404).json({ error: 'Data not found' });
        }

        // 4. RESPONSE: Version Info
        if (type === 'version') {
            const match = latestFile.pathname.match(/data_v(\d+)\.zip/);
            const versionTimestamp = match ? parseInt(match[1]) : new Date(latestFile.uploadedAt).getTime();
            return response.status(200).json({ timestamp: versionTimestamp });
        } 

        // 5. RESPONSE: Redirect to Download
        else {
            // Use 307 Temporary Redirect to prevent caching of the redirect itself
            // Append random query param to the destination URL as well
            const cacheBustUrl = `${latestFile.url}?cb=${Date.now()}`;
            return response.redirect(307, cacheBustUrl);
        }

    } catch (e: any) {
        console.error("API Error:", e);
        return response.status(500).json({ error: e.message || 'Unknown error' });
    }
  }

  // POST: Generate Token for Upload
  if (request.method === 'POST') {
    const body = request.body;

    try {
      const jsonResponse = await handleUpload({
        body,
        request,
        onBeforeGenerateToken: async (pathname) => {
          if (!pathname.startsWith(DATA_FILE_PREFIX) || !pathname.endsWith('.zip')) {
             throw new Error('Invalid filename format. Must be data_v{timestamp}.zip');
          }

          return {
            allowedContentTypes: ['application/zip', 'application/x-zip-compressed', 'application/octet-stream'],
            tokenPayload: JSON.stringify({
              userId: 'admin',
            }),
          };
        },
        onUploadCompleted: async ({ blob, tokenPayload }) => {
          console.log('New data version uploaded:', blob.pathname);
        },
      });

      return response.status(200).json(jsonResponse);
    } catch (error: any) {
      return response.status(400).json({ error: error.message || 'Upload failed' });
    }
  }

  return response.status(405).json({ error: 'Method not allowed' });
}

