          console.error("Auto-sync error:", err);
          if (force) {
            setError("Veri güncellenemedi. İnternet bağlantınızı kontrol edin.");
          }
      } finally {
          setIsLoading(false);
      }
  };

  const handleLogin = (userData: User) => {
    setUser(userData);
    setIsDataLoaded(false); 
    setMasterData([]);
    // Trigger sync after login
    performSmartDataSync();
  };

